	end)
	self:bind(UserInputService.InputEnded, function(input)
		if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
			return
		end
		local drag = self.activeDrag
		self.activeDrag = nil
		if drag and type(drag.Ended) == "function" then
			invokeCallback("Slider drag end", drag.Ended, input)
		end
	end)
	task.defer(function()
		self:fitViewport()
	end)

	return self
end

function Window:bind(signal, callback)
	local connection = signal:Connect(callback)
	self.connections[#self.connections + 1] = connection
	return connection
end

function Window:addCleanup(callback)
	if type(callback) == "function" then
		self.cleanups[#self.cleanups + 1] = callback
	end
	return callback
end

function Window:openPopup(owner, handlers)
	if self.activePopup and self.activePopup.Owner ~= owner then
		self:closePopup()
	end
	handlers = type(handlers) == "table" and handlers or {}
	handlers.Owner = owner
	self.activePopup = handlers
	return handlers
end

function Window:closePopup(owner)
	local popup = self.activePopup
	if not popup or owner and popup.Owner ~= owner then
		return false
	end
	self.activePopup = nil
	if type(popup.Close) == "function" then
		invokeCallback("Close popup", popup.Close)
	end
	return true
end

function Window:setSidebarWidth(width)
	width = math.clamp(tonumber(width) or self.sidebarWidth or 184, 140, 320)
	self.sidebarWidth = width
	if self.collapsed then
		return self
	end
	self.sidebar.Size = UDim2.new(0, width, 1, 0)
	self.divider.Position = UDim2.fromOffset(width, 0)
	self.content.Position = UDim2.fromOffset(width + 1, 0)
	self.content.Size = UDim2.new(1, -(width + 1), 1, 0)
	return self
end

function Window:setToggleKey(key)
	self.toggleKey = key
	return self
end

function Window:setHeaderStatus(text, kind)
	if not self.headerSystemLabel or not self.headerSystemLabel.Parent then
		return self
	end
	local T = self.theme
	self.headerSystemLabel.Text = tostring(text or "SYSTEM ONLINE")
	if self.headerSystemDot then
		self.headerSystemDot.BackgroundColor3 = kind == "error" and T.Error
			or kind == "warn" and T.Gold
			or T.Success
	end
	return self
end

function Window:setNotifySide(side)
	local normalized = string.lower(tostring(side or "Right"))
	local left = normalized == "left" or normalized == "bottomleft" or normalized == "top-left"
	self.notifySide = left and "Left" or "Right"
	if self.toastHolder then
		self.toastHolder.AnchorPoint = left and Vector2.new(0, 1) or Vector2.new(1, 1)
		self.toastHolder.Position = left and UDim2.new(0, 18, 1, -18) or UDim2.new(1, -18, 1, -18)
		local layout = self.toastHolder:FindFirstChildOfClass("UIListLayout")
		if layout then
			layout.HorizontalAlignment = left and Enum.HorizontalAlignment.Left or Enum.HorizontalAlignment.Right
		end
	end
	return self
end

function Window:setDPIScale(value)
	self.dpiScale = math.clamp(tonumber(value) or 1, 0.65, 1.5)
	if self.windowScale then
		self.windowScale.Scale = self.dpiScale
	end
	return self
end

function Window:setFont(font)
	if not self.screen or typeof(font) ~= "EnumItem" then
		return self
	end
	for _, object in ipairs(self.screen:GetDescendants()) do
		if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
			object.Font = font
		end
	end
	return self
end

function Window:fitViewport()
	if not self.scaleModel then
		return
	end
	local vp = viewport()
	local w, h = self.baseSize.X.Offset, self.baseSize.Y.Offset
	local scale = math.clamp(math.min(vp.X / (w + 36), vp.Y / (h + 36), 1), 0.5, 1)
	tween(self.scaleModel, TI_MED, { Scale = scale })
end

function Window:setVisible(on)
	if self.visible == on then
		return
	end
	self.visible = on
	if not on then
		self:closePopup()
	end
	if self.openButton then
		self.openButton.Visible = not on
	end
	if on then
		self.root.Visible = true
		self.main.Visible = true
		self.windowScale.Scale = 0.12
		tween(self.windowScale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = self.dpiScale or 1 })
		tween(self.shadow, TI_MED, { ImageTransparency = 0.55 })
	else
		tween(self.windowScale, TweenInfo.new(0.22, Enum.EasingStyle.Quart, Enum.EasingDirection.In), { Scale = 0.12 })
		tween(self.shadow, TI_FAST, { ImageTransparency = 1 })
		task.delay(0.21, function()
			if not self.visible and self.root.Parent then
				self.root.Visible = false
			end
		end)
	end
end

function Window:toggleZoom()
	local vp = viewport()
	if self.maximized then
		self.maximized = false
		tween(self.root, TI_SMOOTH, {
			Size = self.restoreSize or self.baseSize,
			Position = self.restorePosition or UDim2.fromScale(0.5, 0.5),
		})
	else
		self.maximized = true
		self.restoreSize = self.root.Size
		self.restorePosition = self.root.Position
		tween(self.root, TI_SMOOTH, {
			Size = UDim2.fromOffset(math.max(620, vp.X - 24), math.max(380, vp.Y - 24)),
			Position = UDim2.fromOffset(math.round(vp.X / 2), math.round(vp.Y / 2)),
		})
	end
end

function Window:setCollapsed(on)
	if self.collapsed == on then
		return
	end
	self.collapsed = on
	self:closePopup()
	local collapsedWidth = self.touch and 52 or 46
	local width = on and collapsedWidth or self.sidebarWidth
	self.miniTitle.Visible = on
	self.fullTitle.Visible = not on
	self.titleStar.Visible = not on
	self.supportBadge.Visible = not on
	self.searchBox.Visible = not on
	self.searchIconButton.Visible = on
	tween(self.searchHolder, TI_SMOOTH, {
		Position = UDim2.new(0, on and 8 or 14, 1, -50),
		Size = on and UDim2.fromOffset(collapsedWidth - 22, self.touch and 30 or 26)
			or UDim2.new(1, -28, 0, self.touch and 30 or 26),
	})
	tween(self.sidebar, TI_SMOOTH, { Size = UDim2.new(0, width, 1, 0) })
	tween(self.divider, TI_SMOOTH, { Position = UDim2.fromOffset(width, 0) })
	tween(self.content, TI_SMOOTH, {
		Position = UDim2.fromOffset(width + 1, 0),
		Size = UDim2.new(1, -(width + 1), 1, 0),
	})
	tween(self.collapseChevron, TI_SMOOTH, { Rotation = on and 180 or 0 })
	for _, page in ipairs(self.pages) do
		tween(page.navLabel, TI_FAST, { TextTransparency = on and 1 or 0 })
		tween(page.navIcon, TI_SMOOTH, { Position = UDim2.fromOffset(on and 17 or 15, page.navIconY) })
		tween(page.navButton, TI_SMOOTH, {
			Position = UDim2.fromOffset(on and 6 or 12, 0),
			Size = UDim2.new(1, on and -12 or -24, 0, page.navHeight),
		})
	end
	if on and self.searchBox:IsFocused() then
		self.searchBox:ReleaseFocus()
		self.searchBox.Text = ""
	end
end

-- ===== pages =====
function Window:CreatePage(name, icon)
	local T = self.theme
	local page = make("ScrollingFrame", {
		Name = name .. "Page",
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(0, 66),
		Size = UDim2.new(1, 0, 1, -66),
		Visible = false,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollBarThickness = 6,
		ScrollBarImageColor3 = T.Accent,
		ScrollBarImageTransparency = 0.12,
		ScrollingEnabled = true,
		ElasticBehavior = Enum.ElasticBehavior.WhenScrollable,
	}, self.content)
	make("UIPadding", {
		PaddingTop = UDim.new(0, 4),
		PaddingBottom = UDim.new(0, 20),
	}, page)
	local fullColumn = make("Frame", {
		Name = "Full",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(20, 0),
		Size = UDim2.new(1, -52, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
	}, page)
	make("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 12),
	}, fullColumn)

	make("TextLabel", {
		Name = "PageTitle",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 34),
		Font = Enum.Font.GothamBold,
		Text = tostring(name),
		TextSize = 22,
		TextColor3 = T.Title,
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = -1000,
	}, fullColumn)
	make("TextLabel", {
		Name = "PageSubtitle",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 20),
		Font = Enum.Font.GothamMedium,
		Text = "MAMMOZ HUB CONTROL CENTER",
		TextSize = 12,
		TextColor3 = Color3.fromRGB(200, 220, 245),
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = -999,
	}, fullColumn)

	-- nav button
	local navHeight = self.touch and 46 or 44
	local navButton = make("TextButton", {
		Name = name,
		BackgroundColor3 = T.NavActive,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(12, 0),
		Size = UDim2.new(1, -24, 0, navHeight),
		Text = "",
		AutoButtonColor = false,
		LayoutOrder = #self.pages + 1,
	}, self.nav)
	corner(navButton, 6)
	local navIcon, setNavIconColor = renderIcon(navButton, icon or "code", 14, Color3.new(1, 1, 1))
	navIcon.Position = UDim2.fromOffset(15, navHeight / 2)
	local navLabel = make("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(35, 0),
		Size = UDim2.new(1, -39, 1, 0),
		Font = Enum.Font.GothamBold,
		Text = name,
		TextSize = 14,
		TextColor3 = T.NavIdle,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		ZIndex = 2,
	}, navButton)

	local pageObj = {
		name = name,
		icon = icon or "code",
		frame = page,
		column = fullColumn,
		navButton = navButton,
		navIcon = navIcon,
		navLabel = navLabel,
		navIconY = navHeight / 2,
		navHeight = navHeight,
		setNavIconColor = setNavIconColor,
		order = 0,
		visible = false,
		window = self,
		cards = {},
	}

	local function highlight()
		tween(navButton, TI_MED, { BackgroundTransparency = 0 })
		tween(navLabel, TI_MED, { TextColor3 = Color3.new(1, 1, 1) })
		setNavIconColor(Color3.new(1, 1, 1), TI_MED)
	end
	local function idle()
		tween(navButton, TI_MED, { BackgroundTransparency = 1 })
		tween(navLabel, TI_MED, { TextColor3 = T.NavIdle })
		setNavIconColor(T.NavIdle, TI_MED)
	end
	pageObj.highlight = highlight
	pageObj.idle = idle

	self:bind(navButton.MouseEnter, function()
		if not pageObj.visible then
			tween(navButton, TI_FAST, { BackgroundTransparency = 0.4 })
		end
	end)
	self:bind(navButton.MouseLeave, function()
		if not pageObj.visible then
			tween(navButton, TI_FAST, { BackgroundTransparency = 1 })
		end
	end)
	self:bind(navButton.MouseButton1Click, function()
		self:SelectPage(pageObj)
	end)

	self.pages[#self.pages + 1] = pageObj
	if #self.pages == 1 then
		self:SelectPage(pageObj)
	end

	return setmetatable(pageObj, Page)
end

function Window:SelectPage(page)
	self:closePopup()
	for _, p in ipairs(self.pages) do
		local active = (p == page)
		p.visible = active
		p.frame.Visible = active
		if active then
			p.highlight()
		else
			p.idle()
		end
	end
	-- move nav marker
	if page then
		if self.headerPage then
			self.headerPage.Text = string.upper(tostring(page.name or "DASHBOARD"))
		end
		self.navMarker.Visible = true
		tween(self.navMarker, TI_MED, {
			Position = UDim2.fromOffset(0, page.navButton.Position.Y.Offset + page.navHeight / 2),
		})
	end
end

-- ===== toasts =====
function Window:Notify(title, body, kind)
	if self.cleaning or not self.toastHolder.Parent then
		return
	end
	local T = self.theme
	local tint = kind == "success" and T.Success
		or kind == "error" and T.Error
		or kind == "primary" and T.Primary
		or T.Accent
	self.toastOrder = self.toastOrder + 1
	local toast = make("Frame", {
		Name = "Toast",
		Size = UDim2.fromOffset(268, 56),
		BackgroundColor3 = T.Card,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		LayoutOrder = self.toastOrder,
		ZIndex = 101,
	}, self.toastHolder)
	corner(toast, 7)
	local toastLine = stroke(toast, T.CardLine, 1)
	local accent = make("Frame", {
		BackgroundColor3 = tint,
		BorderSizePixel = 0,
		Size = UDim2.fromOffset(3, 56),
		ZIndex = 102,
	}, toast)
	corner(accent, 999)
	local heading = make("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(14, 8),
		Size = UDim2.new(1, -24, 0, 16),
		Font = Enum.Font.GothamBold,
		Text = title,
		TextSize = 11,
		TextColor3 = T.Title,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTransparency = 1,
		ZIndex = 102,
	}, toast)
	local detail = make("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(14, 25),
		Size = UDim2.new(1, -24, 0, 21),
		Font = Enum.Font.GothamMedium,
		Text = body,
		TextSize = 10,
		TextColor3 = Color3.fromRGB(235, 247, 255),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextWrapped = true,
		TextTransparency = 1,
		ZIndex = 102,
	}, toast)
	tween(toast, TI_MED, { BackgroundTransparency = 0 })
	tween(toastLine, TI_MED, { Transparency = 0 })
	tween(heading, TI_MED, { TextTransparency = 0 })
	tween(detail, TI_MED, { TextTransparency = 0 })
	local duration = 3
	task.delay(duration, function()
		if toast and toast.Parent then
			tween(toast, TI_MED, { BackgroundTransparency = 1 })
			tween(heading, TI_MED, { TextTransparency = 1 })
			tween(detail, TI_MED, { TextTransparency = 1 })
			task.wait(0.2)
			if toast.Parent then
				toast:Destroy()
			end
		end
	end)
end

function Window:Destroy()
	self.cleaning = true
	self:closePopup()
	for _, cleanup in ipairs(self.cleanups) do
		pcall(cleanup)
	end
	table.clear(self.cleanups)
	for _, connection in ipairs(self.connections) do
		pcall(function()
			connection:Disconnect()
		end)
	end
	if self.screen and self.screen.Parent then
		self.screen:Destroy()
	end
end

-- ===== page / cards =====
Page = {}
Page.__index = Page

function Page:CreateCard(title, order)
	local T = self.window.theme
	local frame = make("CanvasGroup", {
		Name = title,
		BackgroundColor3 = T.Card,
		BackgroundTransparency = 0.04,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = order or (#self.cards + 1),
		GroupTransparency = 1,
	}, self.column)
	-- Mark native so legacy styling won't stomp the card surface.
	frame:SetAttribute("MammozUI", true)
	corner(frame, 10)
	local cardStroke = stroke(frame, T.CardLine, 0.10, 1.2)
	make("UIGradient", {
		Color = ColorSequence.new(T.Card, T.CardBottom),
		Rotation = 90,
	}, frame)
	-- Accent bar across the top edge of the card.
	make("Frame", {
		Name = "CardAccent",
		BackgroundColor3 = T.Accent,
		BackgroundTransparency = 0,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 3),
		LayoutOrder = -2,
	}, frame)
	make("UIPadding", {
		PaddingLeft = UDim.new(0, 16),
		PaddingRight = UDim.new(0, 16),
		PaddingTop = UDim.new(0, 14),
		PaddingBottom = UDim.new(0, 16),
	}, frame)
	make("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 12),
	}, frame)
	-- Title row, with a thin divider below it separating header from body.
	local titleHolder = make("Frame", {
		Name = "CardTitleRow",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 24),
		LayoutOrder = -1,
	}, frame)
	local cardTitle = make("TextLabel", {
		Name = "CardTitle",
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 1, 0),
		Font = Enum.Font.GothamBlack,
		Text = title,
		TextSize = 15,
		TextColor3 = Color3.fromRGB(255, 255, 255),
		TextXAlignment = Enum.TextXAlignment.Left,
	}, titleHolder)
	local divider = make("Frame", {
		Name = "CardDivider",
		BackgroundColor3 = T.CardLine,
		BackgroundTransparency = 0.55,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 1),
		LayoutOrder = 0,
	}, frame)

	local card = setmetatable({
		frame = frame,
		order = 0,
		window = self.window,
		page = self,
	}, Card)
	self.cards[#self.cards + 1] = card

	-- intro fade (staggered)
	tween(frame, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, 0, false, 0.035 * #self.cards), { GroupTransparency = 0 })
	return card
end

function Page:nextOrder()
	return #self.cards + 1
end

-- ===== card elements =====
Card = {}
Card.__index = Card

function Card:nextOrder()
	self.order = self.order + 1
	return self.order
end

function Card:AddLabel(text, note)
	local T = self.window.theme
	local label = make("TextLabel", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 14),
		AutomaticSize = Enum.AutomaticSize.Y,
		Font = note and Enum.Font.GothamMedium or Enum.Font.GothamSemibold,
		Text = text,
		TextSize = note and 12 or 14,
		-- Keep both note and primary text bright so nothing in a Card reads
		-- as gray on the dark background.
		TextColor3 = note and Color3.fromRGB(235, 247, 255) or Color3.fromRGB(255, 255, 255),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		TextWrapped = true,
		LayoutOrder = self:nextOrder(),
	}, self.frame)
	return label
end

function Card:AddButton(text, callback)
	local T = self.window.theme
	local h = self.window.touch and 48 or 44
	local button = make("TextButton", {
		Size = UDim2.new(1, 0, 0, h),
		BackgroundColor3 = T.ElementHover,
		BorderSizePixel = 0,
		Text = "",
		AutoButtonColor = false,
		LayoutOrder = self:nextOrder(),
	}, self.frame)
	-- Mark as native Mammoz control so legacy styling won't overwrite it
	button:SetAttribute("MammozUI", true)
	corner(button, 8)
	-- Gradient goes light->element (NOT into Card) so the button stands apart
	-- from the card surface instead of blending into it.
	make("UIGradient", {
		Color = ColorSequence.new(T.ElementHover, T.Element),
		Rotation = 90,
	}, button)
	local line = stroke(button, T.ElementLine, 0, 1.4)
	-- Accent bar on the left edge of the button.
	local accentBar = make("Frame", {
		Name = "AccentBar",
		BackgroundColor3 = T.Accent,
		BackgroundTransparency = 0.35,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(0, 0),
		Size = UDim2.fromOffset(3, 1),
		ZIndex = 2,
	}, button)
	corner(accentBar, 2)
	local label = make("TextLabel", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, -16, 1, 0),
		Position = UDim2.fromOffset(16, 0),
		Font = Enum.Font.GothamBold,
		Text = text,
		TextSize = 13,
		TextColor3 = Color3.fromRGB(255, 255, 255),
		TextXAlignment = Enum.TextXAlignment.Left,
		ZIndex = 2,
	})
	label.Parent = button
	self.window:bind(button.MouseEnter, function()
		tween(line, TI_FAST, { Color = T.Accent, Transparency = 0 })
		tween(button, TI_FAST, { BackgroundColor3 = T.FieldRaised })
		tween(accentBar, TI_FAST, { BackgroundTransparency = 0 })
	end)
	self.window:bind(button.MouseLeave, function()
		tween(line, TI_FAST, { Color = T.ElementLine, Transparency = 0 })
		tween(button, TI_FAST, { BackgroundColor3 = T.ElementHover })
		tween(accentBar, TI_FAST, { BackgroundTransparency = 0.35 })
	end)
	self.window:bind(button.MouseButton1Click, function()
		if callback then
			spawnCallback("Button: " .. tostring(text), callback, label, button)
		end
	end)
	return button, label
end

function Card:AddInput(config, callback)
	config = config or {}
	local T = self.window.theme
	local touch = self.window.touch
	local h = touch and 48 or 44
	local inputRow = make("Frame", {
		BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, h),
		LayoutOrder = self:nextOrder(),
	}, self.frame)
	if config.Label then
		make("TextLabel", {
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(0, 0),
			Size = UDim2.new(0, 180, 1, 0),
			Font = Enum.Font.GothamBold,
			Text = config.Label,
			TextSize = 13,
			TextColor3 = Color3.fromRGB(255, 255, 255),
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Center,
			TextTruncate = Enum.TextTruncate.AtEnd,
		}, inputRow)
	end
	local labelOffset = config.Label and 190 or 0
	local inputHolder = make("Frame", {
		Position = UDim2.fromOffset(labelOffset, 0),
		Size = UDim2.new(1, -labelOffset, 0, h),
		BackgroundColor3 = T.ElementHover,
		BorderSizePixel = 0,
		ClipsDescendants = true,
	}, inputRow)
	inputHolder:SetAttribute("MammozUI", true)
	corner(inputHolder, 8)
	local inputStroke = stroke(inputHolder, T.ElementLine, 0, 1.4)
	make("UIGradient", {
		Color = ColorSequence.new(T.ElementHover, T.Element),
		Rotation = 90,
	}, inputHolder)
	local keyInput = make("TextBox", {
		Name = "Input",
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(8, 0),
		Size = UDim2.new(1, -16, 1, 0),
		Font = Enum.Font.GothamMedium,
		PlaceholderText = config.Placeholder or "",
		PlaceholderColor3 = Color3.fromRGB(195, 218, 240),
		Text = config.Default or "",
		TextSize = 13,
		TextColor3 = Color3.fromRGB(255, 255, 255),
		TextXAlignment = Enum.TextXAlignment.Left,
		ClearTextOnFocus = false,
		MultiLine = false,
		TextEditable = true,
	}, inputHolder)

	if config.Masked then
		keyInput.TextTransparency = 1
		local bullet = utf8.char(0x2022)
		local inputFocused = false
		local scrollOffset = 0
		local selection = make("Frame", {
			Name = "SelectionHighlight",
			BackgroundColor3 = T.AccentBright,
			BorderSizePixel = 0,
			Position = UDim2.fromOffset(8, 3),
			Size = UDim2.fromOffset(0, h - 6),
			Visible = false,
			ZIndex = keyInput.ZIndex + 1,
		}, inputHolder)
		corner(selection, 2)
		local mask = make("TextLabel", {
			BackgroundColor3 = T.AccentBright,
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(8, 0),
			Size = UDim2.new(1, -16, 1, 0),
			Font = Enum.Font.GothamMedium,
			Text = config.Placeholder or "Paste your key here",
			TextSize = 11,
			TextColor3 = Color3.fromRGB(195, 218, 240),
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			ZIndex = keyInput.ZIndex + 2,
		}, inputHolder)
		local caret = make("Frame", {
			Name = "TextCaret",
			BackgroundColor3 = T.AccentBright,
			BorderSizePixel = 0,
			Position = UDim2.fromOffset(8, 4),
			Size = UDim2.fromOffset(2, h - 8),
			Visible = false,
			ZIndex = keyInput.ZIndex + 3,
		}, inputHolder)
		local function bulletWidth(count)
			if count <= 0 then
				return 0
			end
			return TextService:GetTextSize(string.rep(bullet, count), keyInput.TextSize, keyInput.Font, Vector2.new(10000, h)).X
		end
		local function refreshEditor()
			local length = #keyInput.Text
			local cursor = keyInput.CursorPosition
			if cursor < 1 then
				cursor = length + 1
			end
			cursor = math.clamp(cursor, 1, length + 1)
			local available = math.max(0, inputHolder.AbsoluteSize.X - 16)
			local contentWidth = bulletWidth(length)
			local cursorWidth = bulletWidth(cursor - 1)
			if cursorWidth - scrollOffset > available then
				scrollOffset = cursorWidth - available
			elseif cursorWidth - scrollOffset < 0 then
				scrollOffset = cursorWidth
			end
			scrollOffset = math.clamp(scrollOffset, 0, math.max(0, contentWidth - available))
			mask.Position = UDim2.fromOffset(8 - scrollOffset, 0)
			mask.Size = UDim2.new(1, -16 + scrollOffset, 1, 0)
			local selectionStart = keyInput.SelectionStart
			local hasSelection = inputFocused and selectionStart >= 1 and selectionStart ~= cursor and length > 0
			if hasSelection then
				selectionStart = math.clamp(selectionStart, 1, length + 1)
				local first = math.min(selectionStart, cursor) - 1
				local last = math.max(selectionStart, cursor) - 1
				local left = math.clamp(bulletWidth(first) - scrollOffset, 0, available)
				local right = math.clamp(bulletWidth(last) - scrollOffset, 0, available)
				selection.Position = UDim2.fromOffset(8 + left, 3)
				selection.Size = UDim2.fromOffset(math.max(1, right - left), h - 6)
				selection.Visible = right > left
			else
				selection.Visible = false
			end
			caret.Position = UDim2.fromOffset(8 + math.clamp(cursorWidth - scrollOffset, 0, available), 4)
			caret.Visible = inputFocused and not hasSelection
		end
		local function refreshMask()
			local length = #keyInput.Text
			mask.Text = length == 0 and (config.Placeholder or "Paste your key here") or string.rep(bullet, math.min(length, 64))
			mask.TextColor3 = length == 0 and Color3.fromRGB(190, 214, 238) or Color3.fromRGB(255, 255, 255)
			refreshEditor()
		end
		self.window:bind(keyInput:GetPropertyChangedSignal("Text"), refreshMask)
		self.window:bind(keyInput:GetPropertyChangedSignal("CursorPosition"), refreshEditor)
		self.window:bind(keyInput:GetPropertyChangedSignal("SelectionStart"), refreshEditor)
		self.window:bind(inputHolder:GetPropertyChangedSignal("AbsoluteSize"), refreshEditor)
		self.window:bind(keyInput.Focused, function()
			inputFocused = true
			tween(inputStroke, TI_MED, { Color = T.Accent })
			refreshEditor()
		end)
		self.window:bind(keyInput.FocusLost, function(enter)
			inputFocused = false
			selection.Visible = false
			caret.Visible = false
			tween(inputStroke, TI_MED, { Color = T.ElementLine })
			if callback then
				invokeCallback("Input: " .. tostring(config.Label or config.Title or "Input"), callback, keyInput.Text, false, enter)
			end
		end)
		refreshMask()
	else
		self.window:bind(keyInput.Focused, function()
			tween(inputStroke, TI_MED, { Color = T.Accent })
		end)
		self.window:bind(keyInput.FocusLost, function(enter)
			tween(inputStroke, TI_MED, { Color = T.ElementLine })
			if callback then
				invokeCallback("Input: " .. tostring(config.Label or config.Title or "Input"), callback, keyInput.Text, false, enter)
			end
		end)
		self.window:bind(keyInput:GetPropertyChangedSignal("Text"), function()
			if callback and keyInput:IsFocused() then
				invokeCallback("Input change: " .. tostring(config.Label or config.Title or "Input"), callback, keyInput.Text, true, false)
			end
		end)
	end
	return keyInput, inputHolder
end

function Card:AddToggle(text, default, callback)
	local T = self.window.theme
	local h = self.window.touch and 60 or 56
	local row = make("TextButton", {
		Size = UDim2.new(1, 0, 0, h),
		BackgroundColor3 = T.ElementHover,
		BorderSizePixel = 0,
		Text = "",
		AutoButtonColor = false,
		LayoutOrder = self:nextOrder(),
	}, self.frame)
	row:SetAttribute("MammozUI", true)
	corner(row, 8)
	make("UIGradient", {
		Color = ColorSequence.new(T.ElementHover, T.Element),
		Rotation = 90,
	}, row)
	local line = stroke(row, T.ElementLine, 0, 1.4)
	local accentBar = make("Frame", {
		Name = "AccentBar",
		BackgroundColor3 = T.Accent,
		BackgroundTransparency = 0.35,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(0, 0),
		Size = UDim2.fromOffset(3, 1),
		ZIndex = 2,
	}, row)
	corner(accentBar, 2)
	make("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(16, 0),
		Size = UDim2.new(1, -88, 1, 0),
		Font = Enum.Font.GothamBold,
		Text = text,
		TextSize = 14,
		TextColor3 = Color3.fromRGB(255, 255, 255),
		TextXAlignment = Enum.TextXAlignment.Left,
		ZIndex = 2,
	}, row)
	local knobW = 44
	local knob = make("Frame", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -16, 0.5, 0),
		Size = UDim2.fromOffset(knobW, 24),
		BackgroundColor3 = T.Field,
		BorderSizePixel = 0,
		ZIndex = 3,
	}, row)
	corner(knob, 999)
	local dot = make("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.25, 0.5),
		Size = UDim2.fromOffset(18, 18),
		BackgroundColor3 = T.Dim,
		BorderSizePixel = 0,
		ZIndex = 4,
	}, knob)
	corner(dot, 999)
	local state = default and true or false
	local control = { Instance = row, Value = state, Observers = {} }
	local function render()
		tween(knob, TI_MED, { BackgroundColor3 = state and T.Accent or T.Field })
		tween(dot, TI_MED, { Position = UDim2.fromScale(state and 0.75 or 0.25, 0.5), BackgroundColor3 = state and Color3.new(1, 1, 1) or T.Dim })
	end
	function control:Get()
		return state
	end
	function control:Set(value, silent)
		state = value == true
		self.Value = state
		render()
		if not silent and callback then
			spawnCallback("Toggle: " .. tostring(text), callback, state)
		end
		if not silent then
			for _, observer in ipairs(self.Observers) do
				spawnCallback("Toggle observer: " .. tostring(text), observer, state)
			end
		end
		return self
	end
	function control:SetValue(value)
		return self:Set(value)
	end
	function control:Toggle()
		return self:Set(not state)
	end
	function control:OnChanged(observer)
		if type(observer) == "function" then
			self.Observers[#self.Observers + 1] = observer
		end
		return self
	end
	function control:SetDesc()
		return self
	end
	function control:Disable(disabled)
		row.Active = disabled ~= false and false or true
		return self
	end
	render()
	self.window:bind(row.MouseEnter, function()
		tween(line, TI_FAST, { Color = T.Accent, Transparency = 0 })
		tween(row, TI_FAST, { BackgroundColor3 = T.FieldRaised })
		tween(accentBar, TI_FAST, { BackgroundTransparency = 0 })
	end)
	self.window:bind(row.MouseLeave, function()
		tween(line, TI_FAST, { Color = T.ElementLine, Transparency = 0 })
		tween(row, TI_FAST, { BackgroundColor3 = T.ElementHover })
		tween(accentBar, TI_FAST, { BackgroundTransparency = 0.35 })
	end)
	self.window:bind(row.MouseButton1Click, function()
		control:Set(not state)
	end)
	return control
end

function Card:AddSlider(text, min, max, default, callback)
	local T = self.window.theme
	local touch = self.window.touch
	local h = touch and 64 or 60
	local container = make("Frame", {
		BackgroundColor3 = T.ElementHover,
		BackgroundTransparency = 0,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, h),
		LayoutOrder = self:nextOrder(),
	}, self.frame)
	container:SetAttribute("MammozUI", true)
	corner(container, 8)
	local sliderLine = stroke(container, T.ElementLine, 0, 1.4)
	local accentBar = make("Frame", {
		Name = "AccentBar",
		BackgroundColor3 = T.Accent,
		BackgroundTransparency = 0.35,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(0, 0),
		Size = UDim2.fromOffset(3, 1),
		ZIndex = 2,
	}, container)
	corner(accentBar, 2)
	make("UIGradient", {
		Color = ColorSequence.new(T.ElementHover, T.Element),
		Rotation = 90,
	}, container)
	make("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(16, 0),
		Size = UDim2.new(0, 230, 1, 0),
		Font = Enum.Font.GothamBold,
		Text = text,
		TextSize = 14,
		TextColor3 = Color3.fromRGB(255, 255, 255),
		TextXAlignment = Enum.TextXAlignment.Left,
	}, container)
	local valueLabel = make("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.new(1, -64, 0, 0),
		Size = UDim2.fromOffset(54, 24),
		Font = Enum.Font.GothamBold,
		Text = tostring(default),
		TextSize = 13,
		TextColor3 = Color3.fromRGB(255, 255, 255),
		TextXAlignment = Enum.TextXAlignment.Right,
	}, container)
	local track = make("TextButton", {
		Position = UDim2.fromOffset(260, 30),
		Size = UDim2.new(1, -280, 0, 10),
		BackgroundColor3 = T.Field,
		BorderSizePixel = 0,
		Text = "",
		AutoButtonColor = false,
	}, container)
	corner(track, 999)
	local fill = make("Frame", {
		Size = UDim2.fromScale(0, 1),
		BackgroundColor3 = T.Accent,
		BorderSizePixel = 0,
	}, track)
	corner(fill, 999)
	local knob = make("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(18, 18),
		BackgroundColor3 = T.Value,
		BorderSizePixel = 0,
		ZIndex = 2,
	}, track)
	corner(knob, 999)

	local minv, maxv = min or 0, max or 100
	local value = math.clamp(default or minv, minv, maxv)
	local control = { Instance = container, Value = value, Observers = {} }
	local function ratio()
		return (value - minv) / math.max(0.0001, maxv - minv)
	end
	local function render()
		local r = ratio()
		tween(fill, TI_FAST, { Size = UDim2.fromScale(r, 1) })
		tween(knob, TI_FAST, { Position = UDim2.fromScale(r, 0.5) })
		valueLabel.Text = tostring(math.floor(value * 100) / 100)
	end
	function control:Get()
		return value
	end
	function control:Set(nextValue, silent)
		value = math.clamp(tonumber(nextValue) or minv, minv, maxv)
		self.Value = value
		render()
		if not silent and callback then
			spawnCallback("Slider: " .. tostring(text), callback, value)
		end
		if not silent then
			for _, observer in ipairs(self.Observers) do
				spawnCallback("Slider observer: " .. tostring(text), observer, value)
			end
		end
		return self
	end
	function control:SetValue(nextValue)
		return self:Set(nextValue)
	end
	function control:OnChanged(observer)
		if type(observer) == "function" then
			self.Observers[#self.Observers + 1] = observer
		end
		return self
	end
	function control:SetDesc()
		return self
	end
	render()
	local function updateFromInput(input)
		if input.UserInputType ~= Enum.UserInputType.MouseMovement
			and input.UserInputType ~= Enum.UserInputType.MouseButton1
			and input.UserInputType ~= Enum.UserInputType.Touch then
			return
		end
		local abs = track.AbsoluteSize.X
		if abs <= 0 then
			return
		end
		local rel = math.clamp((input.Position.X - track.AbsolutePosition.X) / abs, 0, 1)
		control:Set(minv + rel * (maxv - minv))
	end
	self.window:bind(track.InputBegan, function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			self.window.activeDrag = {
				Owner = control,
				Update = updateFromInput,
			}
			updateFromInput(input)
		end
	end)
	return control
end

function Card:AddDropdown(text, options, default, callback)
	local T = self.window.theme
	local touch = self.window.touch
	local win = self.window
	local h = touch and 58 or 54
	local values = type(options) == "table" and options or {}
	local current = default ~= nil and default or values[1]
	local container = make("TextButton", {
		Size = UDim2.new(1, 0, 0, h),
		BackgroundColor3 = T.ElementHover,
		BorderSizePixel = 0,
		Text = "",
		AutoButtonColor = false,
		LayoutOrder = self:nextOrder(),
	}, self.frame)
	container:SetAttribute("MammozUI", true)
	corner(container, 8)
	make("UIGradient", {
		Color = ColorSequence.new(T.ElementHover, T.Element),
		Rotation = 90,
	}, container)
	local line = stroke(container, T.ElementLine, 0, 1.4)
	local accentBar = make("Frame", {
		Name = "AccentBar",
		BackgroundColor3 = T.Accent,
		BackgroundTransparency = 0.35,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(0, 0),
		Size = UDim2.fromOffset(3, 1),
		ZIndex = 2,
	}, container)
	corner(accentBar, 2)
	make("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(16, 0),
		Size = UDim2.new(0, 224, 1, 0),
		Font = Enum.Font.GothamBold,
		Text = tostring(text or "Dropdown"),
		TextSize = 14,
		TextColor3 = Color3.fromRGB(255, 255, 255),
		TextXAlignment = Enum.TextXAlignment.Left,
	}, container)
	local valueHolder = make("Frame", {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -14, 0.5, 0),
		Size = UDim2.new(0.48, 0, 0, 34),
		BackgroundColor3 = T.FieldRaised,
		BorderSizePixel = 0,
	}, container)
	corner(valueHolder, 6)
	stroke(valueHolder, T.ElementLine, 0, 1.2)
	local valueLabel = make("TextLabel", {
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(12, 0),
		Size = UDim2.new(1, -40, 1, 0),
		Font = Enum.Font.GothamMedium,
		Text = tostring(current or "Select"),
		TextSize = 13,
		TextColor3 = Color3.fromRGB(235, 247, 255),
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, valueHolder)
	local chev = makeChevron(valueHolder, 10, T.Label)
	chev.Position = UDim2.new(1, -13, 0.5)
	chev.AnchorPoint = Vector2.new(1, 0.5)

	local list = make("ScrollingFrame", {
		Name = "MammozDropdown",
		Visible = false,
		BackgroundColor3 = T.Card,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		CanvasSize = UDim2.new(),
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollingEnabled = true,
		ScrollBarThickness = 5,
		ScrollBarImageColor3 = T.Accent,
		ScrollBarImageTransparency = 0.08,
		ZIndex = 80,
	}, win.main)
	corner(list, 7)
	stroke(list, T.Accent, 0.08)
	local listLayout = make("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 4),
	}, list)
	make("UIPadding", {
		PaddingTop = UDim.new(0, 6),
		PaddingBottom = UDim.new(0, 6),
		PaddingLeft = UDim.new(0, 6),
		PaddingRight = UDim.new(0, 8),
	}, list)

	local open = false
	local entries = {}
	local entryConnections = {}
	local popupHeight = 48
	local proxy = { Instance = container, Value = current, Observers = {} }
	local popupInputBegan
	local popupInputChanged

	local function clearEntryConnections()
		for _, connection in ipairs(entryConnections) do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(entryConnections)
	end

	local function bindEntry(signal, callbackFn)
		local connection = signal:Connect(function(...)
			invokeCallback("Dropdown entry: " .. tostring(text), callbackFn, ...)
		end)
		entryConnections[#entryConnections + 1] = connection
		return connection
	end

	local function syncPosition()
		local cAp, cAs = container.AbsolutePosition, container.AbsoluteSize
		local mAp, mAs = win.main.AbsolutePosition, win.main.AbsoluteSize
		local width = math.clamp(math.floor(cAs.X * 0.48), 240, 420)
		local x = cAp.X - mAp.X + cAs.X - width - 14
		local below = cAp.Y - mAp.Y + cAs.Y + 5
		local y = below + popupHeight <= mAs.Y - 10 and below or math.max(10, cAp.Y - mAp.Y - popupHeight - 5)
		list.Position = UDim2.fromOffset(x, y)
		list.Size = UDim2.fromOffset(width, popupHeight)
	end

	local function setOpen(on, fromManager)
		open = on == true and #values > 0
		if open then
			syncPosition()
			win:openPopup(proxy, {
				Close = function()
					setOpen(false, true)
				end,
				InputBegan = function(input)
					if popupInputBegan then
						popupInputBegan(input)
					end
				end,
				InputChanged = function(input)
					if popupInputChanged then
						popupInputChanged(input)
					end
				end,
			})
		elseif not fromManager then
			win:closePopup(proxy)
		end
		list.Visible = open
		tween(chev, TI_FAST, { Rotation = open and 180 or 0 })
		tween(line, TI_FAST, { Color = open and T.Accent or T.ElementLine })
	end

	local function choose(value, fireCallback)
		current = value
		proxy.Value = value
		valueLabel.Text = tostring(value ~= nil and value or "Select")
		setOpen(false)
		if fireCallback and callback then
			spawnCallback("Dropdown: " .. tostring(text), callback, value)
		end
		if fireCallback then
			for _, observer in ipairs(proxy.Observers) do
				spawnCallback("Dropdown observer: " .. tostring(text), observer, value)
			end
		end
	end

	local function rebuild(nextValues)
		values = type(nextValues) == "table" and nextValues or {}
		clearEntryConnections()
		for _, entry in ipairs(entries) do
			if entry.Parent then
				entry:Destroy()
			end
		end
		table.clear(entries)
		for index, option in ipairs(values) do
			local optionValue = option
			local button = make("TextButton", {
				Size = UDim2.new(1, 0, 0, touch and 40 or 36),
				BackgroundColor3 = T.FieldRaised,
				BorderSizePixel = 0,
				Text = tostring(optionValue),
				TextSize = 13,
				TextColor3 = Color3.fromRGB(235, 247, 255),
				Font = Enum.Font.GothamMedium,
				TextXAlignment = Enum.TextXAlignment.Left,
				AutoButtonColor = false,
				LayoutOrder = index,
				ZIndex = 81,
			}, list)
			button:SetAttribute("MammozUI", true)
			corner(button, 5)
			make("UIPadding", { PaddingLeft = UDim.new(0, 12) }, button)
			entries[#entries + 1] = button
			bindEntry(button.MouseEnter, function()
				tween(button, TI_FAST, { BackgroundColor3 = T.NavActive, TextColor3 = Color3.fromRGB(255, 255, 255) })
			end)
			bindEntry(button.MouseLeave, function()
				tween(button, TI_FAST, { BackgroundColor3 = T.FieldRaised, TextColor3 = Color3.fromRGB(235, 247, 255) })
			end)
			bindEntry(button.MouseButton1Click, function()
				choose(optionValue, true)
			end)
		end
		local itemHeight = touch and 40 or 36
		local contentHeight = 12 + #values * itemHeight + math.max(0, #values - 1) * 4
		popupHeight = math.clamp(contentHeight, 48, touch and 260 or 234)
		list.CanvasSize = UDim2.fromOffset(0, contentHeight)
		if current == nil and values[1] ~= nil then
			choose(values[1], false)
		end
		if open then
			syncPosition()
		end
	end

	function proxy:Get()
		return current
	end
	function proxy:Set(value)
		choose(value, true)
		return self
	end
	function proxy:Select(value)
		return self:Set(value)
	end
	function proxy:SetValue(value)
		return self:Set(value)
	end
	function proxy:SetValues(nextValues)
		rebuild(nextValues)
		return self
	end
	function proxy:SetOptions(nextValues)
		return self:SetValues(nextValues)
	end
	function proxy:Refresh(nextValues, value)
		if type(nextValues) == "table" then
			rebuild(nextValues)
		end
		if value ~= nil then
			choose(value, false)
		end
		return self
	end
	function proxy:Open()
		setOpen(true)
		return self
	end
	function proxy:Close()
		setOpen(false)
		return self
	end
	function proxy:OnChanged(observer)
		if type(observer) == "function" then
			self.Observers[#self.Observers + 1] = observer
		end
		return self
	end
	function proxy:SetDesc()
		return self
	end

	rebuild(values)
	choose(current, false)
	win:bind(container:GetPropertyChangedSignal("AbsolutePosition"), function()
		if open then
			syncPosition()
		end
	end)
	win:bind(container.MouseEnter, function()
		tween(line, TI_FAST, { Color = T.Accent })
	end)
	win:bind(container.MouseLeave, function()
		if not open then
			tween(line, TI_FAST, { Color = T.ElementLine })
		end
	end)
	win:bind(container.MouseButton1Click, function()
		setOpen(not open)
	end)
	popupInputBegan = function(input)
		if not open then
			return
		end
		if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
			return
		end
		local point = input.Position
		local cAp, cAs = container.AbsolutePosition, container.AbsoluteSize
		local lAp, lAs = list.AbsolutePosition, list.AbsoluteSize
		local inContainer = point.X >= cAp.X and point.X <= cAp.X + cAs.X and point.Y >= cAp.Y and point.Y <= cAp.Y + cAs.Y
		local inList = point.X >= lAp.X and point.X <= lAp.X + lAs.X and point.Y >= lAp.Y and point.Y <= lAp.Y + lAs.Y
		if not inContainer and not inList then
			setOpen(false)
		end
	end
	popupInputChanged = function(input)
		if not open or input.UserInputType ~= Enum.UserInputType.MouseWheel then
			return
		end
		local point = UserInputService:GetMouseLocation()
		local ap, size = list.AbsolutePosition, list.AbsoluteSize
		if point.X < ap.X or point.X > ap.X + size.X or point.Y < ap.Y or point.Y > ap.Y + size.Y then
			return
		end
		local maxY = math.max(0, list.AbsoluteCanvasSize.Y - list.AbsoluteWindowSize.Y)
		list.CanvasPosition = Vector2.new(0, math.clamp(list.CanvasPosition.Y - input.Position.Z * 48, 0, maxY))
	end
	win:addCleanup(function()
		win:closePopup(proxy)
		clearEntryConnections()
		if list and list.Parent then
			list:Destroy()
		end
	end)
	return proxy
end

return MammozUI

    end,
    ["MammozLegacyLayout.lua"] = function()
-- Mammoz full-layout adapter for scripts that build Roblox UI with Instance.new.
-- Menu controls are rebuilt inside MammozUI. Auxiliary screens such as cursors,
-- overlays, and HUDs are preserved as real Roblox UI when they are not menus.

local Adapter = {}

local function envTable()
	return (getgenv and getgenv()) or _G
end

local function reportError(context, err)
	local reporter = envTable().__MAMMOZ_REPORT_ERROR
	if type(reporter) == "function" then
		pcall(reporter, tostring(context or "Legacy layout"), tostring(err or "Unknown error"))
	elseif type(warn) == "function" then
		warn(("[Mammoz] %s: %s"):format(tostring(context or "Legacy layout"), tostring(err or "Unknown error")))
	end
end

local function traceback(message)
	return debug and debug.traceback and debug.traceback(tostring(message), 2) or tostring(message)
end

local function safeCall(callback, ...)
	local ok, result = pcall(callback, ...)
	if ok then
		return result
	end
	return nil
end

local function trim(value)
	local text = tostring(value or "")
	text = text:gsub("<.->", "")
	text = text:gsub("^%s+", ""):gsub("%s+$", "")
	text = text:gsub("%s+", " ")
	return text
end

local function lower(value)
	return string.lower(trim(value))
end

local function usefulText(value)
	local text = trim(value)
	if text == "" or text == "-" or text == "_" then
		return nil
	end
	return string.sub(text, 1, 96)
end

local GENERIC_NAMES = {
	frame = true,
	textbutton = true,
	imagebutton = true,
	textbox = true,
	textlabel = true,
	scrollingframe = true,
	canvasgroup = true,
	gui = true,
	main = true,
	content = true,
	page = true,
	container = true,
}

local function usefulName(object)
	local name = object and trim(object.Name) or ""
	local normalized = string.lower(name)
	if name == "" or GENERIC_NAMES[normalized] then
		return nil
	end
	if normalized:match("^name%d*$") or normalized:match("^[a-z][a-z][a-z]$") then
		return nil
	end
	return string.sub(name, 1, 56)
end

local function descendants(root)
	if not root then
		return {}
	end
	return safeCall(function()
		return root:GetDescendants()
	end) or {}
end

local function children(root)
	if not root then
		return {}
	end
	return safeCall(function()
		return root:GetChildren()
	end) or {}
end

local function isA(object, className)
	return object and safeCall(function()
		return object:IsA(className)
	end) == true
end

local function isDescendant(object, ancestor)
	if not object or not ancestor then
		return false
	end
	return safeCall(function()
		return object:IsDescendantOf(ancestor)
	end) == true
end

local function classObjects(root, classNames)
	local wanted = {}
	for _, className in ipairs(classNames) do
		wanted[className] = true
	end
	local result = {}
	for className in pairs(wanted) do
		if isA(root, className) then
			result[#result + 1] = root
			break
		end
	end
	for _, object in ipairs(descendants(root)) do
		for className in pairs(wanted) do
			if isA(object, className) then
				result[#result + 1] = object
				break
			end
		end
	end
	return result
end

local function interactiveObjects(root)
	return classObjects(root, { "TextButton", "ImageButton", "TextBox" })
end

local function textLabels(root)
	return classObjects(root, { "TextLabel" })
end

local function estimateSize(object, fallback)
	fallback = fallback or Vector2.new(1120, 700)
	local absolute = safeCall(function()
		return object.AbsoluteSize
	end)
	if absolute and absolute.X > 1 and absolute.Y > 1 then
		return absolute
	end
	local size = safeCall(function()
		return object.Size
	end)
	if size then
		return Vector2.new(
			math.max(1, fallback.X * size.X.Scale + size.X.Offset),
			math.max(1, fallback.Y * size.Y.Scale + size.Y.Offset)
		)
	end
	return fallback
end

local function objectPosition(object)
	local absolute = safeCall(function()
		return object.AbsolutePosition
	end)
	if absolute then
		return absolute
	end
	local position = safeCall(function()
		return object.Position
	end)
	if position then
		return Vector2.new(position.X.Offset, position.Y.Offset)
	end
	return Vector2.new()
end

local function objectOrder(object, index)
	local layoutOrder = safeCall(function()
		return object.LayoutOrder
	end) or 0
	local position = objectPosition(object)
	return layoutOrder * 1000000 + math.floor(position.Y) * 1000 + math.floor(position.X) + index / 1000
end

local function sortedObjects(list)
	local indexed = {}
	for index, object in ipairs(list) do
		indexed[#indexed + 1] = {
			object = object,
			order = objectOrder(object, index),
		}
	end
	table.sort(indexed, function(a, b)
		return a.order < b.order
	end)
	local result = {}
	for _, item in ipairs(indexed) do
		result[#result + 1] = item.object
	end
	return result
end

local function findMainRoot(screen)
	local best
	local bestScore = -1
	for _, object in ipairs(children(screen)) do
		if isA(object, "GuiObject") then
			local size = estimateSize(object)
			local score = size.X * size.Y + #interactiveObjects(object) * 10000 + #textLabels(object) * 100
			if score > bestScore then
				best = object
				bestScore = score
			end
		end
	end
	return best
end

local function directInteractiveCount(root)
	local count = 0
	for _, object in ipairs(interactiveObjects(root)) do
		local nestedPage = false
		local parent = object.Parent
		while parent and parent ~= root do
			if isA(parent, "ScrollingFrame") then
				nestedPage = true
				break
			end
			parent = parent.Parent
		end
		if not nestedPage then
			count += 1
		end
	end
	return count
end

local function findPageCandidates(root)
	local rootSize = estimateSize(root)
	local candidates = {}
	for _, object in ipairs(descendants(root)) do
		if isA(object, "ScrollingFrame") then
			local size = estimateSize(object, rootSize)
			local wide = size.X >= math.max(220, rootSize.X * 0.38)
			local tall = size.Y >= math.max(150, rootSize.Y * 0.30)
			if wide and tall and #interactiveObjects(object) > 0 then
				candidates[#candidates + 1] = object
			end
		end
	end

	if #candidates == 0 then
		for _, object in ipairs(descendants(root)) do
			if isA(object, "Frame") or isA(object, "CanvasGroup") then
				local size = estimateSize(object, rootSize)
				local wide = size.X >= math.max(220, rootSize.X * 0.45)
				local tall = size.Y >= math.max(150, rootSize.Y * 0.35)
				if wide and tall and directInteractiveCount(object) > 0 then
					candidates[#candidates + 1] = object
				end
			end
		end
	end

	local deepest = {}
	for _, candidate in ipairs(candidates) do
		local containsCandidate = false
		for _, other in ipairs(candidates) do
			if other ~= candidate and isDescendant(other, candidate) then
				containsCandidate = true
				break
			end
		end
		if not containsCandidate then
			deepest[#deepest + 1] = candidate
		end
	end

	if #deepest == 0 then
		deepest[1] = root
	end
	return sortedObjects(deepest)
end

local function findNavButtons(root, pages)
	if #pages <= 1 then
		return {}, nil
	end
	local rootSize = estimateSize(root)
	local pageSet = {}
	for _, page in ipairs(pages) do
		pageSet[page] = true
	end

	local containers = {}
	for _, object in ipairs(descendants(root)) do
		if isA(object, "ScrollingFrame") and not pageSet[object] then
			local size = estimateSize(object, rootSize)
			local buttons = classObjects(object, { "TextButton", "ImageButton" })
			if size.X < rootSize.X * 0.38 and #buttons >= math.min(2, #pages) then
				containers[#containers + 1] = { frame = object, buttons = buttons, size = size }
			end
		end
	end

	table.sort(containers, function(a, b)
		local target = math.max(1, #pages)
		local aPos = objectPosition(a.frame)
		local bPos = objectPosition(b.frame)
		local aScore = math.abs(#a.buttons - target) * 10000 + aPos.X * 2 - a.size.Y
		local bScore = math.abs(#b.buttons - target) * 10000 + bPos.X * 2 - b.size.Y
		return aScore < bScore
	end)
	if containers[1] then
		return sortedObjects(containers[1].buttons), containers[1].frame
	end

	local result = {}
	for _, object in ipairs(classObjects(root, { "TextButton" })) do
		local insidePage = false
		for _, page in ipairs(pages) do
			if isDescendant(object, page) then
				insidePage = true
				break
			end
		end
		local text = usefulText(object.Text)
		local size = estimateSize(object, rootSize)
		if not insidePage and text and size.Y >= 20 and size.Y <= 72 then
			result[#result + 1] = object
		end
	end
	return sortedObjects(result), nil
end

local CONTROL_WORDS = {
	on = true,
	off = true,
	enabled = true,
	disabled = true,
	["true"] = true,
	["false"] = true,
	yes = true,
	no = true,
	x = true,
	click = false,
}

local function isControlWord(text)
	return CONTROL_WORDS[lower(text)] ~= nil
end

local function nearestLabel(button, scope)
	local buttonPos = objectPosition(button)
	local buttonSize = estimateSize(button, estimateSize(scope))
	local best
	local bestScore = math.huge
	for _, label in ipairs(textLabels(scope)) do
		local text = usefulText(label.Text)
		if text and not isControlWord(text) then
			local labelPos = objectPosition(label)
			local labelSize = estimateSize(label, estimateSize(scope))
			local buttonY = buttonPos.Y + buttonSize.Y * 0.5
			local labelY = labelPos.Y + labelSize.Y * 0.5
			local dy = math.abs(buttonY - labelY)
			local sameParentBonus = label.Parent == button.Parent and -60 or 0
			local rowLimit = math.max(28, buttonSize.Y * 0.8 + labelSize.Y * 0.8)
			if dy <= rowLimit then
				local dx = math.abs(buttonPos.X - labelPos.X)
				local score = dy * 5 + dx * 0.02 + sameParentBonus
				if score < bestScore then
					best = label
					bestScore = score
				end
			end
		end
	end
	return best
end

local function controlName(button, scope, fallbackIndex)
	local text = usefulText(safeCall(function()
		return button.Text
	end))
	if text and not isControlWord(text) then
		return text, nil
	end

	local descendantLabels = sortedObjects(textLabels(button))
	for _, label in ipairs(descendantLabels) do
		local childText = usefulText(label.Text)
		if childText and not isControlWord(childText) then
			return childText, label
		end
	end

	local label = nearestLabel(button, scope)
	if label then
		return usefulText(label.Text), label
	end

	return usefulName(button) or ("Control " .. tostring(fallbackIndex)), nil
end

local function looksLikeToggle(button, scope)
	local text = lower(safeCall(function()
		return button.Text
	end))
	if CONTROL_WORDS[text] == true or text == "" and isA(button, "TextButton") then
		local size = estimateSize(button, estimateSize(scope))
		local label = nearestLabel(button, scope)
		if text ~= "" or label or #textLabels(button) > 0 then
			if size.X <= 110 or #children(button) > 0 or size.X >= estimateSize(scope).X * 0.65 then
				return true
			end
		end
	end
	return false
end

local function toggleState(button)
	local text = lower(safeCall(function()
		return button.Text
	end))
	if text == "on" or text == "enabled" or text == "true" or text == "yes" or text == "x" then
		return true
	end
	local color = safeCall(function()
		return button.BackgroundColor3
	end)
	if color and color.G > color.R * 1.2 and color.G > color.B * 0.9 then
		return true
	end
	return false
end

local function connectionList(signal)
	if type(signal) == "table" and signal.__MammozVirtualSignal and type(signal.GetConnections) == "function" then
		return signal:GetConnections()
	end
	if type(getconnections) ~= "function" or not signal then
		return nil
	end
	local ok, result = pcall(getconnections, signal)
	if ok and type(result) == "table" then
		return result
	end
	return nil
end

local function fireSignal(signal, connections, ...)
	if not signal then
		return false
	end
	if type(signal) == "table" and signal.__MammozVirtualSignal and type(signal.Fire) == "function" then
		signal:Fire(...)
		return true
	end
	if type(firesignal) == "function" then
		local ok = pcall(firesignal, signal, ...)
		if ok then
			return true
		end
	end
	connections = connections or connectionList(signal)
	if connections then
		local fired = false
		for _, connection in ipairs(connections) do
			local enabled = safeCall(function()
				return connection.Enabled
			end)
			if enabled ~= false then
				local method = safeCall(function()
					return connection.Fire
				end)
				local callback = safeCall(function()
					return connection.Function
				end)
				if type(method) == "function" then
					task.spawn(method, connection, ...)
					fired = true
				elseif type(callback) == "function" then
					task.spawn(callback, ...)
					fired = true
				end
			end
		end
		return fired
	end
	return false
end

local function buttonSignals(button)
	local names = { "MouseButton1Click", "MouseButton1Down", "Activated", "MouseButton1Up" }
	local result = {}
	for _, name in ipairs(names) do
		local signal = safeCall(function()
			return button[name]
		end)
		if signal then
			result[#result + 1] = {
				signal = signal,
				connections = connectionList(signal),
			}
		end
	end
	return result
end

local function activateButton(button)
	local signals = buttonSignals(button)
	for _, item in ipairs(signals) do
		if item.connections and #item.connections > 0 then
			return fireSignal(item.signal, item.connections)
		end
	end
	local fired = false
	for _, item in ipairs(signals) do
		fired = fireSignal(item.signal, item.connections) or fired
	end
	return fired
end

local function writeTextBox(box, value, commit)
	safeCall(function()
		box.Text = tostring(value or "")
	end)
	if commit then
		local signal = safeCall(function()
			return box.FocusLost
		end)
		fireSignal(signal, connectionList(signal), true)
	end
end

local function isStructuralButton(button, navSet)
	if navSet[button] then
		return true
	end
	local name = lower(button.Name)
	local text = lower(safeCall(function()
		return button.Text
	end))
	if name:find("close", 1, true) or name:find("minimize", 1, true) or name:find("maxbtn", 1, true) then
		return true
	end
	if text == "discord" or text == "get key" or text == "copy hwid" or text == "vip" then
		return false
	end
	local parentName = lower(button.Parent and button.Parent.Name or "")
	if (text == "-" or text == "_") and (parentName:find("top", 1, true) or parentName:find("header", 1, true)) then
		return true
	end
	return false
end

local function looksLikeKnob(button)
	local text = trim(safeCall(function()
		return button.Text
	end))
	local size = estimateSize(button)
	local name = lower(button.Name)
	local parentName = lower(button.Parent and button.Parent.Name or "")
	if text == "" and size.X <= 26 and size.Y <= 26 then
		return true
	end
	if name:find("knob", 1, true) or parentName == "fill" or parentName == "bar" then
		return true
	end
	return false
end

local function uniqueOptionButtons(root)
	local values = {}
	local buttons = {}
	local seen = {}
	for _, button in ipairs(sortedObjects(classObjects(root, { "TextButton" }))) do
		local text = usefulText(button.Text)
		if text and not isControlWord(text) then
			local key = lower(text)
			if not seen[key] then
				seen[key] = true
				values[#values + 1] = text
				buttons[text] = button
			end
		end
	end
	return values, buttons
end

local function nestedDropdowns(page)
	local groups = {}
	local claimed = {}
	for _, frame in ipairs(classObjects(page, { "Frame", "CanvasGroup" })) do
		local directButtons = {}
		local optionFrame
		for _, child in ipairs(children(frame)) do
			if isA(child, "TextButton") then
				directButtons[#directButtons + 1] = child
			elseif isA(child, "ScrollingFrame") and #classObjects(child, { "TextButton" }) >= 2 then
				optionFrame = child
			end
		end
		if optionFrame and directButtons[1] then
			local values, optionButtons = uniqueOptionButtons(optionFrame)
			if #values >= 2 then
				local trigger = directButtons[1]
				local triggerText = usefulText(trigger.Text) or "Selection"
				local label = triggerText:match("^%s*(.-)%s*:%s*") or triggerText
				groups[#groups + 1] = {
					frame = frame,
					trigger = trigger,
					optionFrame = optionFrame,
					label = label,
					values = values,
					buttons = optionButtons,
				}
				claimed[trigger] = true
				for _, button in pairs(optionButtons) do
					claimed[button] = true
				end
			end
		end
	end
	return groups, claimed
end

local function connect(state, signal, callback)
	if not signal then
		return nil
	end
	local connection = safeCall(function()
		return signal:Connect(function(...)
			local args = table.pack(...)
			local ok, err = xpcall(function()
				callback(table.unpack(args, 1, args.n))
			end, traceback)
			if not ok then
				reportError(state.context or "Legacy UI event", err)
			end
		end)
	end)
	if connection then
		state.connections[#state.connections + 1] = connection
	end
	return connection
end

local function pageTitle(page, navButton, index)
	local navText = navButton and usefulText(safeCall(function()
		return navButton.Text
	end))
	if navText then
		return navText
	end
	for _, label in ipairs(sortedObjects(textLabels(page))) do
		local text = usefulText(label.Text)
		local size = safeCall(function()
			return label.TextSize
		end) or 0
		if text and size >= 14 and #text <= 48 then
			return text
		end
	end
	return usefulName(page) or ("PAGE " .. tostring(index))
end

local ICON_SEQUENCE = { "home", "star", "shield", "user", "search", "gear", "code" }

local function addDropdown(card, group, state)
	local current = group.values[1]
	local triggerText = usefulText(group.trigger.Text)
	if triggerText then
		local selected = triggerText:match(":%s*(.+)$")
		if selected then
			current = trim(selected)
		end
	end
	local proxy = card:Dropdown(group.label, group.values, current, function(value)
		local original = group.buttons[value]
		if original then
			activateButton(original)
		end
	end)
	local refreshVersion = 0
	local function scheduleRefresh()
		refreshVersion += 1
		local version = refreshVersion
		task.delay(0.1, function()
			if version ~= refreshVersion then
				return
			end
			if not group.optionFrame.Parent then
				return
			end
			local values, buttons = uniqueOptionButtons(group.optionFrame)
			group.values = values
			group.buttons = buttons
			if proxy and type(proxy.Refresh) == "function" then
				proxy:Refresh(values)
			end
		end)
	end
	connect(state, group.optionFrame.DescendantAdded, scheduleRefresh)
	connect(state, group.optionFrame.DescendantRemoving, scheduleRefresh)
	return proxy
end

local function addButtonControl(card, button, scope, index, usedLabels, state)
	local name, sourceLabel = controlName(button, scope, index)
	if sourceLabel then
		usedLabels[sourceLabel] = true
	end
	if looksLikeToggle(button, scope) then
		local proxy = card:Toggle(name, toggleState(button), function()
			activateButton(button)
		end)
		local function sync()
			if proxy and type(proxy.Set) == "function" then
				proxy:Set(toggleState(button), true)
			end
		end
		connect(state, button:GetPropertyChangedSignal("Text"), sync)
		connect(state, button:GetPropertyChangedSignal("BackgroundColor3"), sync)
		return proxy
	end
	return card:Button(name, function()
		activateButton(button)
	end)
end

local function addInputControl(card, box, scope, index, usedLabels, state)
	local name, sourceLabel = controlName(box, scope, index)
	if sourceLabel then
		usedLabels[sourceLabel] = true
	end
	local proxy = card:Input({
		Title = name,
		Default = safeCall(function()
			return box.Text
		end) or "",
		Placeholder = safeCall(function()
			return box.PlaceholderText
		end) or "",
	}, function(value, focused, enter)
		writeTextBox(box, value, enter or not focused)
	end)
	connect(state, box:GetPropertyChangedSignal("Text"), function()
		if proxy and proxy.Instance and not proxy.Instance:IsFocused() then
			proxy.Value = box.Text
			proxy.Instance.Text = box.Text
		end
	end)
	return proxy
end

local function addReadouts(card, scope, usedLabels, state)
	local added = 0
	for _, label in ipairs(sortedObjects(textLabels(scope))) do
		if not usedLabels[label] then
			local text = usefulText(label.Text)
			local name = lower(label.Name)
			local multiline = text and (text:find("\n", 1, true) ~= nil or #text > 54)
			local statusLike = name:find("status", 1, true) or name:find("headline", 1, true) or name:find("info", 1, true)
			if text and (multiline or statusLike or #interactiveObjects(scope) == 0) and added < 12 then
				local mirror = card:Label(text, true)
				connect(state, label:GetPropertyChangedSignal("Text"), function()
					if mirror and mirror.Parent then
						mirror.Text = label.Text
					end
				end)
				added += 1
			end
		end
	end
end

local function buildPage(window, sourcePage, name, icon, navSet, state)
	local page = window:Page(name, icon)
	local card = page:Card("FUNCTIONS")
	local record = {
		source = sourcePage,
		page = page,
		card = card,
		usedLabels = {},
	}
	state.records[#state.records + 1] = record
	state.pageSources[sourcePage] = record
	local dropdownGroups, claimed = nestedDropdowns(sourcePage)
	for _, group in ipairs(dropdownGroups) do
		if not state.dropdownFrames[group.frame] then
			state.dropdownFrames[group.frame] = addDropdown(card, group, state) or true
		end
		state.mapped[group.trigger] = true
		for _, optionButton in pairs(group.buttons) do
			state.mapped[optionButton] = true
		end
	end

	local index = 0
	for _, object in ipairs(sortedObjects(interactiveObjects(sourcePage))) do
		if not claimed[object] and not isStructuralButton(object, navSet) then
			if isA(object, "TextBox") then
				index += 1
				state.mapped[object] = addInputControl(card, object, sourcePage, index, record.usedLabels, state) or true
			elseif not looksLikeKnob(object) then
				index += 1
				state.mapped[object] = addButtonControl(card, object, sourcePage, index, record.usedLabels, state) or true
			end
		end
	end
	addReadouts(card, sourcePage, record.usedLabels, state)
	return record
end

local function recordForObject(state, object)
	local best
	local bestArea = math.huge
	for _, record in ipairs(state.records) do
		if object == record.source or isDescendant(object, record.source) then
			local size = estimateSize(record.source)
			local area = math.max(1, size.X * size.Y)
			if area < bestArea then
				best = record
				bestArea = area
			end
		end
	end
	return best
end

local function dynamicRecord(window, root, state)
	if state.dynamicRecord then
		return state.dynamicRecord
	end
	local page = window:Page("DYNAMIC", "star")
	state.dynamicRecord = {
		source = root,
		page = page,
		card = page:Card("LIVE CONTROLS"),
		usedLabels = {},
	}
	state.records[#state.records + 1] = state.dynamicRecord
	return state.dynamicRecord
end

local function refreshDynamicControls(window, root, state)
	for _, record in ipairs(state.records) do
		local dropdownGroups = nestedDropdowns(record.source)
		for _, group in ipairs(dropdownGroups) do
			if not state.dropdownFrames[group.frame] then
				state.dropdownFrames[group.frame] = addDropdown(record.card, group, state) or true
			end
			state.mapped[group.trigger] = state.mapped[group.trigger] or true
			for _, optionButton in pairs(group.buttons) do
				state.mapped[optionButton] = state.mapped[optionButton] or true
			end
		end
	end

	for _, object in ipairs(sortedObjects(interactiveObjects(root))) do
		if not state.mapped[object] and not isStructuralButton(object, state.navSet) and not looksLikeKnob(object) then
			local record = recordForObject(state, object) or dynamicRecord(window, root, state)
			state.dynamicIndex += 1
			if isA(object, "TextBox") then
				state.mapped[object] = addInputControl(record.card, object, record.source, state.dynamicIndex, record.usedLabels, state) or true
			else
				state.mapped[object] = addButtonControl(record.card, object, record.source, state.dynamicIndex, record.usedLabels, state) or true
			end
		end
	end
end

local function scheduleDynamicRefresh(window, root, state)
	state.dynamicVersion += 1
	local version = state.dynamicVersion
	task.delay(0.12, function()
		if state.stopped or version ~= state.dynamicVersion or not root.Parent then
			return
		end
		local ok, err = xpcall(function()
			refreshDynamicControls(window, root, state)
		end, traceback)
		if not ok then
			reportError(state.context or "Dynamic legacy UI", err)
		end
	end)
end

local function settingValue(spec)
	local environment = envTable()
	if spec.Store == "global" then
		return tonumber(environment[spec.Key]) or tonumber(spec.Default) or tonumber(spec.Min) or 0
	end
	local settings = environment.Setting or _G.Setting
	local value = settings and settings[spec.Key]
	if type(value) == "table" then
		value = value[1]
	end
	return tonumber(value) or tonumber(spec.Default) or tonumber(spec.Min) or 0
end

local function setSettingValue(spec, value)
	value = math.floor((tonumber(value) or 0) + 0.5)
	local environment = envTable()
	if spec.Store == "global" then
		environment[spec.Key] = value
		_G[spec.Key] = value
		return
	end
	local settings = environment.Setting or _G.Setting
	if type(settings) ~= "table" then
		return
	end
	if type(settings[spec.Key]) == "table" then
		settings[spec.Key][1] = value
	else
		settings[spec.Key] = value
	end
end

local function addSliderPage(window, sliderSpecs)
	if type(sliderSpecs) ~= "table" or #sliderSpecs == 0 then
		return
	end
	local page = window:Page("TUNING", "gear")
	local card = page:Card("VALUES")
	for _, spec in ipairs(sliderSpecs) do
		card:Slider(
			tostring(spec.Label or spec.Key or "Value"),
			tonumber(spec.Min) or 0,
			tonumber(spec.Max) or 100,
			settingValue(spec),
			function(value)
				setSettingValue(spec, value)
			end,
			tostring(spec.Suffix or "")
		)
	end
end

local function standaloneOptionFrames(root, pages, navContainer)
	local result = {}
	for _, frame in ipairs(classObjects(root, { "ScrollingFrame" })) do
		local insidePage = false
		for _, page in ipairs(pages) do
			if frame == page or isDescendant(frame, page) then
				insidePage = true
				break
			end
		end
		if not insidePage and frame ~= navContainer then
			local values, buttons = uniqueOptionButtons(frame)
			if #values >= 2 then
				result[#result + 1] = {
					frame = frame,
					values = values,
					buttons = buttons,
				}
			end
		end
	end
	return result
end

local function addSelectionsPage(window, groups, state)
	if #groups == 0 then
		return
	end
	local page = window:Page("SELECTIONS", "search")
	local card = page:Card("OPTIONS")
	for index, group in ipairs(groups) do
		group.label = usefulName(group.frame) or ("Selection " .. tostring(index))
		group.optionFrame = group.frame
		group.trigger = { Text = "" }
		addDropdown(card, group, state)
	end
end

local function detectTitle(screen, root, configured)
	if usefulText(configured) then
		return usefulText(configured)
	end
	local labels = textLabels(root)
	table.sort(labels, function(a, b)
		local aSize = safeCall(function() return a.TextSize end) or 0
		local bSize = safeCall(function() return b.TextSize end) or 0
		return aSize > bSize
	end)
	for _, label in ipairs(labels) do
		local text = usefulText(label.Text)
		if text and #text <= 64 then
			return text
		end
	end
	return usefulName(screen) or "MAMMOZ SCRIPT"
end

local function statusScreenName(screen)
	local name = lower(screen and screen.Name or "")
	if name:find("esp", 1, true) or name:find("black", 1, true) or name:find("overlay", 1, true)
		or name:find("crosshair", 1, true) or name:find("aimline", 1, true) then
		return false
	end
	return name:find("status", 1, true) ~= nil
		or name:find("kaitun", 1, true) ~= nil
		or name:find("loader", 1, true) ~= nil
end

local function containsAny(text, patterns)
	for _, pattern in ipairs(patterns) do
		if text:find(pattern, 1, true) then
			return true
		end
	end
	return false
end

local NOTIFICATION_NAMES = { "notification", "notifications", "notify", "toast" }
local AUXILIARY_NAMES = {
	"cursor", "crosshair", "overlay", "blackscreen", "black_screen", "aimline",
	"esp", "fpslabel", "larbshow", "hud", "chams",
}
local MINIMIZER_NAMES = {
	"vectorimagebutton", "togglegui", "mobileui", "minimizer", "openbutton", "logogui",
}

local function classifyScreen(screen, root, interactions, labels)
	local name = lower(screen and screen.Name or "")
	if containsAny(name, NOTIFICATION_NAMES) then
		return "notification"
	end
	if containsAny(name, AUXILIARY_NAMES) then
		return "auxiliary"
	end
	if containsAny(name, MINIMIZER_NAMES) and interactions <= 2 then
		return "suppress"
	end
	if not root or interactions == 0 and labels == 0 then
		return "auxiliary"
	end
	if interactions == 0 and not statusScreenName(screen) then
		return "auxiliary"
	end
	return "primary"
end

local function notificationItem(root, object)
	local current = object
	while current and current.Parent and current.Parent ~= root do
		current = current.Parent
	end
	if current and current.Parent == root then
		return current
	end
	return object
end

local function notificationText(item)
	local labels = sortedObjects(textLabels(item))
	local values = {}
	for _, label in ipairs(labels) do
		local text = usefulText(safeCall(function()
			return label.Text
		end))
		if text then
			values[#values + 1] = {
				text = text,
				size = tonumber(safeCall(function() return label.TextSize end)) or 0,
			}
		end
	end
	table.sort(values, function(a, b)
		return a.size > b.size
	end)
	if #values == 0 then
		return nil, nil
	end
	if #values == 1 then
		return "Notification", values[1].text
	end
	return values[1].text, values[2].text
end

local function bridgeNotifications(window, screen, root, state)
	state.notificationPending = {}
	state.notificationSeen = {}
	local function queue(object)
		local item = notificationItem(root, object)
		if not item or item == root or state.notificationPending[item] or state.notificationSeen[item] then
			return
		end
		state.notificationPending[item] = true
		task.delay(0.06, function()
			state.notificationPending[item] = nil
			if state.stopped or not item.Parent then
				return
			end
			local title, body = notificationText(item)
			if not title then
				return
			end
			state.notificationSeen[item] = true
			window:Notify(title, body or "", "primary")
		end)
	end

	for _, child in ipairs(children(root)) do
		if #textLabels(child) > 0 then
			queue(child)
		end
	end
	connect(state, root.DescendantAdded, queue)
	safeCall(function()
		screen.Enabled = false
	end)
end

local function ensureWindow(UI, session, screen, root, config)
	if session.window and session.window.raw then
		return session.window
	end
	local current = UI.LastWindow
	if current and current ~= session.startWindow and current.raw then
		session.window = current
		return current
	end
	local title = detectTitle(screen, root, config.Title)
	local cleanName = tostring(screen.Name or "Legacy"):gsub("[^%w_]", "")
	session.window = UI.Window({
		Title = title,
		Name = "MammozConverted_" .. cleanName,
		BadgeText = "FULL MAMMOZ LAYOUT",
	})
	return session.window
end

local function disconnectState(state)
	state.stopped = true
	for _, connection in ipairs(state.connections) do
		safeCall(function()
			connection:Disconnect()
		end)
	end
	table.clear(state.connections)
end

local function adoptScreen(UI, session, screen, config)
	if not screen or not screen.Parent or session.adopted[screen] then
		return false
	end
	local virtualScreen = type(screen) == "table" and screen.__MammozVirtualNode == true
	if not virtualScreen and (tostring(screen.Name):find("Mammoz", 1, true) or safeCall(function()
		return screen:GetAttribute("MammozUI")
	end) == true) then
		return false
	end
	local root = findMainRoot(screen)
	local interactions = root and #interactiveObjects(root) or 0
	local labels = root and #textLabels(root) or 0
	local kind = classifyScreen(screen, root, interactions, labels)
	local isVirtualScreen = type(screen) == "table" and screen.__MammozVirtualNode == true
	if kind == "auxiliary" then
		if isVirtualScreen and type(config.MaterializeAuxiliary) == "function" then
			local ok, result = pcall(config.MaterializeAuxiliary, screen)
			if not ok then
				reportError(("%s / auxiliary UI"):format(tostring(config.Source or screen.Name)), result)
				return false
			end
			if result then
				session.adopted[screen] = true
				return true
			end
		end
		return false
	elseif kind == "suppress" then
		session.adopted[screen] = true
		if type(config.SuppressAuxiliary) == "function" then
			safeCall(config.SuppressAuxiliary, screen)
		end
		return true
	elseif not root then
		return false
	end

	session.adopted[screen] = true
	local state = {
		connections = {},
		context = tostring(config.Source or screen.Name or "Legacy UI"),
		mapped = {},
		dropdownFrames = {},
		records = {},
		pageSources = {},
		navSet = {},
		dynamicIndex = 0,
		dynamicVersion = 0,
		stopped = false,
	}
	local window = ensureWindow(UI, session, screen, root, config)
	if kind == "notification" then
		bridgeNotifications(window, screen, root, state)
		connect(state, screen.Destroying, function()
			disconnectState(state)
		end)
		session.states[screen] = state
		return true
	end
	local pages = findPageCandidates(root)
	local navButtons, navContainer = findNavButtons(root, pages)
	for _, button in ipairs(navButtons) do
		state.navSet[button] = true
	end

	local usedNames = {}
	for index, sourcePage in ipairs(pages) do
		local name = pageTitle(sourcePage, navButtons[index], index)
		local base = name
		local suffix = 2
		while usedNames[lower(name)] do
			name = base .. " " .. tostring(suffix)
			suffix += 1
		end
		usedNames[lower(name)] = true
		buildPage(window, sourcePage, name, ICON_SEQUENCE[(index - 1) % #ICON_SEQUENCE + 1], state.navSet, state)
	end

	addSelectionsPage(window, standaloneOptionFrames(root, pages, navContainer), state)
	if not session.slidersAdded then
		addSliderPage(window, config.Sliders)
		session.slidersAdded = true
	end

	safeCall(function()
		screen.Enabled = false
	end)
	connect(state, screen:GetPropertyChangedSignal("Enabled"), function()
		if screen.Enabled then
			window.raw:setVisible(true)
			screen.Enabled = false
		end
	end)
	connect(state, root:GetPropertyChangedSignal("Visible"), function()
		window.raw:setVisible(root.Visible)
	end)
	connect(state, root.DescendantAdded, function()
		scheduleDynamicRefresh(window, root, state)
	end)
	connect(state, screen.Destroying, function()
		disconnectState(state)
	end)
	session.states[screen] = state
	return true
end

local function screenParents()
	local result = {}
	local seen = {}
	local function add(parent)
		if parent and not seen[parent] then
			seen[parent] = true
			result[#result + 1] = parent
		end
	end
	for _, getter in ipairs({ gethui, get_hidden_gui }) do
		if type(getter) == "function" then
			add(safeCall(getter))
		end
	end
	add(safeCall(function()
		return game:GetService("CoreGui")
	end))
	add(safeCall(function()
		local player = game:GetService("Players").LocalPlayer
		return player and (player:FindFirstChild("PlayerGui") or player:WaitForChild("PlayerGui", 3))
	end))
	return result
end

local function stopSession(session)
	for _, connection in ipairs(session.watchConnections) do
		safeCall(function()
			connection:Disconnect()
		end)
	end
	table.clear(session.watchConnections)
end

local function scheduleAdoption(UI, session, screen, config)
	if session.pending[screen] then
		return
	end
	session.pending[screen] = true
	local lastChange = os.clock()
	local descendantConnection = screen.DescendantAdded:Connect(function()
		lastChange = os.clock()
	end)
	task.spawn(function()
		local started = os.clock()
		local settle = tonumber(config.SettleDelay) or 0.65
		local timeout = tonumber(config.BuildTimeout) or 5
		while not screen.Parent and os.clock() - started < timeout do
			task.wait(0.05)
		end
		if not screen.Parent then
			safeCall(function()
				descendantConnection:Disconnect()
			end)
			session.pending[screen] = nil
			return
		end
		lastChange = os.clock()
		repeat
			task.wait(0.12)
		until os.clock() - lastChange >= settle or os.clock() - started >= timeout
		safeCall(function()
			descendantConnection:Disconnect()
		end)
		local adopted = false
		if screen.Parent then
			adopted = adoptScreen(UI, session, screen, config)
		end
		session.pending[screen] = nil
		if not adopted and screen.Parent then
			session.retryCounts[screen] = (session.retryCounts[screen] or 0) + 1
			if session.retryCounts[screen] <= 3 then
				task.delay(0.5, function()
					if screen.Parent and not session.adopted[screen] then
						scheduleAdoption(UI, session, screen, config)
					end
				end)
			end
		end
	end)
end

local function createSession(UI)
	local session = {
		startWindow = UI.LastWindow,
		window = nil,
		known = {},
		pending = {},
		adopted = {},
		states = {},
		watchConnections = {},
		retryCounts = {},
		slidersAdded = false,
	}
	function session.Stop()
		stopSession(session)
	end
	return session
end

function Adapter.CreateVirtualSession(UI, config)
	assert(type(UI) == "table", "MammozLegacyLayout.CreateVirtualSession expects MammozCompat")
	config = type(config) == "table" and config or {}
	local environment = envTable()
	local previous = environment.__MAMMOZ_VIRTUAL_LAYOUT_SESSION
	if type(previous) == "table" and type(previous.Stop) == "function" then
		safeCall(previous.Stop)
	end

	local session = createSession(UI)
	function session:Queue(screen)
		if not self.pending[screen] then
			scheduleAdoption(UI, self, screen, config)
		end
		return screen
	end
	environment.__MAMMOZ_VIRTUAL_LAYOUT_SESSION = session
	return session
end

function Adapter.Install(UI, config)
	assert(type(UI) == "table", "MammozLegacyLayout.Install expects the Mammoz compatibility table")
	config = type(config) == "table" and config or {}
	local environment = envTable()
	local previous = environment.__MAMMOZ_FULL_LAYOUT_SESSION
	if type(previous) == "table" and type(previous.Stop) == "function" then
		safeCall(previous.Stop)
	end

	local session = createSession(UI)

	local parents = screenParents()
	for _, parent in ipairs(parents) do
		for _, child in ipairs(children(parent)) do
			if isA(child, "ScreenGui") then
				session.known[child] = true
			end
		end
	end

	local maxGuis = tonumber(config.MaxGuis) or 8
	local captured = 0
	for _, parent in ipairs(parents) do
		local connection = parent.ChildAdded:Connect(function(child)
			if captured >= maxGuis or session.known[child] or not isA(child, "ScreenGui") then
				return
			end
			if tostring(child.Name):find("Mammoz", 1, true) or safeCall(function()
				return child:GetAttribute("MammozUI")
			end) == true then
				return
			end
			session.known[child] = true
			captured += 1
			scheduleAdoption(UI, session, child, config)
		end)
		session.watchConnections[#session.watchConnections + 1] = connection
	end

	environment.__MAMMOZ_FULL_LAYOUT_SESSION = session
	task.delay(tonumber(config.Duration) or 20, function()
		if environment.__MAMMOZ_FULL_LAYOUT_SESSION == session then
			stopSession(session)
			environment.__MAMMOZ_FULL_LAYOUT_SESSION = nil
		end
	end)
	return session
end

return Adapter

    end,
    ["MammozLegacyProxy.lua"] = function()
-- Virtual Roblox UI instances used by the full Mammoz converter.
-- GUI constructors begin as an in-memory tree; menu screens stay virtual while
-- auxiliary screens can be materialized after classification. Non-GUI instances
-- always delegate to Roblox.

local RealInstance = Instance

local Proxy = {}

local function reportError(context, err)
	local environment = (getgenv and getgenv()) or _G
	local reporter = environment and environment.__MAMMOZ_REPORT_ERROR
	if type(reporter) == "function" then
		pcall(reporter, tostring(context or "Virtual UI"), tostring(err or "Unknown error"))
	elseif type(warn) == "function" then
		warn(("[Mammoz] %s: %s"):format(tostring(context or "Virtual UI"), tostring(err or "Unknown error")))
	end
end

