local function safe(callback, ...)
	local ok, result = pcall(callback, ...)
	if ok then
		return result
	end
	return nil
end

local Signal = {}
Signal.__index = Signal

local Connection = {}
Connection.__index = Connection

function Connection:Disconnect()
	self.Connected = false
	self.Enabled = false
end

Connection.disconnect = Connection.Disconnect

function Connection:Disable()
	self.Enabled = false
end

function Connection:Enable()
	if self.Connected then
		self.Enabled = true
	end
end

function Connection:Fire(...)
	if self.Connected and self.Enabled and type(self.Function) == "function" then
		return self.Function(...)
	end
end

local function newSignal(name, owner)
	return setmetatable({
		Name = name,
		__MammozVirtualSignal = true,
		_connections = {},
		_owner = owner,
	}, Signal)
end

function Signal:Connect(callback)
	local connection = setmetatable({
		Connected = true,
		Enabled = true,
		Function = callback,
		Signal = self,
	}, Connection)
	self._connections[#self._connections + 1] = connection
	return connection
end

Signal.connect = Signal.Connect

function Signal:Once(callback)
	local connection
	connection = self:Connect(function(...)
		connection:Disconnect()
		return callback(...)
	end)
	return connection
end

function Signal:GetConnections()
	local result = {}
	for _, connection in ipairs(self._connections) do
		if connection.Connected then
			result[#result + 1] = connection
		end
	end
	return result
end

function Signal:Fire(...)
	local args = table.pack(...)
	for _, connection in ipairs(self:GetConnections()) do
		if connection.Enabled and type(connection.Function) == "function" then
			task.spawn(function()
				local ok, err = xpcall(function()
					connection.Function(table.unpack(args, 1, args.n))
				end, function(message)
					return debug and debug.traceback and debug.traceback(tostring(message), 2) or tostring(message)
				end)
				if not ok then
					local owner = self._owner
					local factory = owner and rawget(owner, "_factory")
					local source = factory and factory.Config and factory.Config.Source or "legacy UI"
					reportError(("%s / %s"):format(tostring(source), tostring(self.Name)), err)
				end
			end)
		end
	end
end

function Signal:Wait()
	local thread = coroutine.running()
	local values
	local connection
	connection = self:Connect(function(...)
		values = table.pack(...)
		connection:Disconnect()
		task.spawn(thread)
	end)
	coroutine.yield()
	return table.unpack(values or {}, 1, values and values.n or 0)
end

local Node = {}
local NodeMeta = {}

local function isVirtual(value)
	return type(value) == "table" and rawget(value, "__MammozVirtualNode") == true
end

local function viewportSize()
	local camera = safe(function()
		return workspace.CurrentCamera
	end)
	local size = camera and safe(function()
		return camera.ViewportSize
	end)
	return size or Vector2.new(1120, 700)
end

local function propertySignal(node, property)
	local signals = rawget(node, "_propertySignals")
	if not signals[property] then
		signals[property] = newSignal(property .. "Changed", node)
	end
	return signals[property]
end

local function eventSignal(node, name)
	local signals = rawget(node, "_signals")
	if not signals[name] then
		signals[name] = newSignal(name, node)
		local real = rawget(node, "_real")
		local realSignal = real and safe(function()
			return real[name]
		end)
		if realSignal and typeof(realSignal) == "RBXScriptSignal" then
			safe(function()
				realSignal:Connect(function(...)
					signals[name]:Fire(...)
				end)
			end)
			signals[name]._realConnected = true
		end
	end
	return signals[name]
end

local function isClass(node, className)
	local own = rawget(node, "_className")
	if own == className or className == "Instance" then
		return true
	end
	if className == "GuiObject" or className == "GuiBase2d" then
		return GUI_OBJECTS[own] == true
	end
	if className == "GuiButton" then
		return GUI_BUTTONS[own] == true
	end
	if className == "LayerCollector" then
		return own == "ScreenGui"
	end
	if className == "UIComponent" then
		return UI_COMPONENTS[own] == true
	end
	if className == "UILayout" then
		return own == "UIListLayout" or own == "UIGridLayout" or own == "UIPageLayout"
	end
	return false
end

local function rootSize(node)
	local parent = rawget(node, "_parent")
	if isVirtual(parent) then
		return parent.AbsoluteSize
	end
	return viewportSize()
end

local function resolveUDim2(value, parentSize)
	if typeof(value) ~= "UDim2" then
		return Vector2.new()
	end
	return Vector2.new(
		parentSize.X * value.X.Scale + value.X.Offset,
		parentSize.Y * value.Y.Scale + value.Y.Offset
	)
end

local function absoluteSize(node)
	if rawget(node, "_real") then
		return safe(function()
			return rawget(node, "_real").AbsoluteSize
		end) or Vector2.new()
	end
	if rawget(node, "_className") == "ScreenGui" then
		return viewportSize()
	end
	local props = rawget(node, "_props")
	local size = resolveUDim2(props.Size, rootSize(node))
	if size.X <= 0 and size.Y <= 0 and UI_COMPONENTS[rawget(node, "_className")] then
		return rootSize(node)
	end
	return size
end

local function absolutePosition(node)
	if rawget(node, "_real") then
		return safe(function()
			return rawget(node, "_real").AbsolutePosition
		end) or Vector2.new()
	end
	local parent = rawget(node, "_parent")
	local parentPosition = isVirtual(parent) and parent.AbsolutePosition or Vector2.new()
	local parentSize = isVirtual(parent) and parent.AbsoluteSize or viewportSize()
	local props = rawget(node, "_props")
	local position = resolveUDim2(props.Position, parentSize)
	local anchor = props.AnchorPoint or Vector2.new()
	local size = absoluteSize(node)
	return parentPosition + position - Vector2.new(size.X * anchor.X, size.Y * anchor.Y)
end

local function contentSize(node)
	local width = 0
	local height = 0
	for _, child in ipairs(rawget(node, "_children")) do
		if isClass(child, "GuiObject") then
			local size = child.AbsoluteSize
			local position = safe(function()
				return child.Position
			end) or UDim2.new()
			width = math.max(width, position.X.Offset + size.X)
			height += math.max(0, size.Y)
		end
	end
	return Vector2.new(width, height)
end

local function removeChild(parent, child)
	if not isVirtual(parent) then
		return
	end
	local list = rawget(parent, "_children")
	for index, current in ipairs(list) do
		if current == child then
			table.remove(list, index)
			eventSignal(parent, "ChildRemoved"):Fire(child)
			break
		end
	end
end

local function propagate(parent, signalName, object)
	local current = parent
	while isVirtual(current) do
		eventSignal(current, signalName):Fire(object)
		current = rawget(current, "_parent")
	end
end

local function addChild(parent, child)
	if not isVirtual(parent) then
		return
	end
	local list = rawget(parent, "_children")
	list[#list + 1] = child
	eventSignal(parent, "ChildAdded"):Fire(child)
	propagate(parent, "DescendantAdded", child)
	for _, descendant in ipairs(child:GetDescendants()) do
		propagate(parent, "DescendantAdded", descendant)
	end
end

local function materialize(node, parent)
	if rawget(node, "_real") then
		rawget(node, "_real").Parent = parent
		return rawget(node, "_real")
	end
	local className = rawget(node, "_className")
	local real = safe(function()
		return RealInstance.new(className)
	end)
	if not real then
		return nil
	end
	rawset(node, "_real", real)
	for key, value in pairs(rawget(node, "_props")) do
		if key ~= "Parent" and key ~= "AbsoluteSize" and key ~= "AbsolutePosition" then
			safe(function()
				real[key] = value
			end)
		end
	end
	for name, signal in pairs(rawget(node, "_signals")) do
		local realSignal = safe(function()
			return real[name]
		end)
		if realSignal and typeof(realSignal) == "RBXScriptSignal" and not signal._realConnected then
			safe(function()
				realSignal:Connect(function(...)
					signal:Fire(...)
				end)
			end)
			signal._realConnected = true
		end
	end
	for _, child in ipairs(rawget(node, "_children")) do
		materialize(child, real)
	end
	real.Parent = parent
	return real
end

local function setParent(node, parent)
	local previous = rawget(node, "_parent")
	if previous == parent then
		return
	end
	if isVirtual(previous) then
		propagate(previous, "DescendantRemoving", node)
		removeChild(previous, node)
	end
	rawset(node, "_parent", parent)

	local className = rawget(node, "_className")
	if isVirtual(parent) then
		addChild(parent, node)
		local parentReal = rawget(parent, "_real")
		if parentReal then
			materialize(node, parentReal)
		end
	elseif parent ~= nil and className ~= "ScreenGui" then
		materialize(node, parent)
	elseif rawget(node, "_real") then
		rawget(node, "_real").Parent = parent
	end
	eventSignal(node, "AncestryChanged"):Fire(node, parent)
	propertySignal(node, "Parent"):Fire()
end

local function defaultProperty(node, key)
	local className = rawget(node, "_className")
	if key == "ClassName" then
		return className
	elseif key == "Name" then
		return className
	elseif key == "Parent" then
		return rawget(node, "_parent")
	elseif key == "AbsoluteSize" or key == "AbsoluteWindowSize" then
		return absoluteSize(node)
	elseif key == "AbsolutePosition" then
		return absolutePosition(node)
	elseif key == "AbsoluteContentSize" or key == "AbsoluteCanvasSize" then
		return contentSize(node)
	elseif key == "Size" or key == "Position" or key == "CanvasSize" then
		return UDim2.new()
	elseif key == "AnchorPoint" or key == "CanvasPosition" then
		return Vector2.new()
	elseif key == "Visible" or key == "Enabled" or key == "Active" or key == "Interactable" then
		return true
	elseif key == "Text" or key == "PlaceholderText" or key == "Image" then
		return ""
	elseif key == "TextSize" then
		return 14
	elseif key == "BackgroundTransparency" or key == "TextTransparency" or key == "ImageTransparency" then
		return 0
	elseif key == "LayoutOrder" or key == "ZIndex" or key == "DisplayOrder" then
		return 0
	elseif key == "Value" then
		return nil
	end
	return nil
end

function Node:IsA(className)
	return isClass(self, className)
end

function Node:GetChildren()
	return table.clone(rawget(self, "_children"))
end

function Node:GetDescendants()
	local result = {}
	local function visit(parent)
		for _, child in ipairs(rawget(parent, "_children")) do
			result[#result + 1] = child
			visit(child)
		end
	end
	visit(self)
	return result
end

function Node:FindFirstChild(name, recursive)
	for _, child in ipairs(rawget(self, "_children")) do
		if child.Name == name then
			return child
		end
	end
	if recursive then
		for _, child in ipairs(self:GetDescendants()) do
			if child.Name == name then
				return child
			end
		end
	end
	return nil
end

function Node:WaitForChild(name, timeout)
	local started = os.clock()
	repeat
		local child = self:FindFirstChild(name)
		if child then
			return child
		end
		task.wait()
	until timeout and os.clock() - started >= timeout
	return nil
end

function Node:FindFirstChildWhichIsA(className, recursive)
	local pool = recursive and self:GetDescendants() or self:GetChildren()
	for _, child in ipairs(pool) do
		if child:IsA(className) then
			return child
		end
	end
	return nil
end

Node.FindFirstChildOfClass = Node.FindFirstChildWhichIsA

function Node:IsDescendantOf(ancestor)
	local current = rawget(self, "_parent")
	while current do
		if current == ancestor then
			return true
		end
		current = isVirtual(current) and rawget(current, "_parent") or nil
	end
	return false
end

function Node:FindFirstAncestor(name)
	local current = rawget(self, "_parent")
	while isVirtual(current) do
		if current.Name == name then
			return current
		end
		current = rawget(current, "_parent")
	end
	return nil
end

function Node:FindFirstAncestorWhichIsA(className)
	local current = rawget(self, "_parent")
	while isVirtual(current) do
		if current:IsA(className) then
			return current
		end
		current = rawget(current, "_parent")
	end
	return nil
end

function Node:GetPropertyChangedSignal(property)
	return propertySignal(self, property)
end

function Node:SetAttribute(name, value)
	rawget(self, "_attributes")[name] = value
	propertySignal(self, "Attribute_" .. name):Fire()
end

function Node:GetAttribute(name)
	return rawget(self, "_attributes")[name]
end

function Node:GetAttributeChangedSignal(name)
	return propertySignal(self, "Attribute_" .. name)
end

function Node:GetAttributes()
	return table.clone(rawget(self, "_attributes"))
end

function Node:ClearAllChildren()
	for _, child in ipairs(self:GetChildren()) do
		child:Destroy()
	end
end

function Node:Destroy()
	if rawget(self, "_destroyed") then
		return
	end
	eventSignal(self, "Destroying"):Fire()
	for _, child in ipairs(self:GetChildren()) do
		child:Destroy()
	end
	setParent(self, nil)
	local real = rawget(self, "_real")
	if real then
		safe(function()
			real:Destroy()
		end)
	end
	rawset(self, "_destroyed", true)
end

Node.Remove = Node.Destroy

function Node:Clone()
	local factory = rawget(self, "_factory")
	local clone = factory.new(rawget(self, "_className"))
	for key, value in pairs(rawget(self, "_props")) do
		clone[key] = value
	end
	for name, value in pairs(rawget(self, "_attributes")) do
		clone:SetAttribute(name, value)
	end
	for _, child in ipairs(self:GetChildren()) do
		local childClone = child:Clone()
		childClone.Parent = clone
	end
	return clone
end

function Node:GetFullName()
	local names = { self.Name }
	local current = rawget(self, "_parent")
	while isVirtual(current) do
		table.insert(names, 1, current.Name)
		current = rawget(current, "_parent")
	end
	return table.concat(names, ".")
end

function Node:IsFocused()
	return rawget(self, "_focused") == true
end

function Node:CaptureFocus()
	rawset(self, "_focused", true)
	eventSignal(self, "Focused"):Fire()
end

function Node:ReleaseFocus(submitted)
	rawset(self, "_focused", false)
	eventSignal(self, "FocusLost"):Fire(submitted == true)
end

function Node:TweenPosition(position, _, _, _, _, callback)
	self.Position = position
	if type(callback) == "function" then
		task.defer(callback)
	end
	return true
end

function Node:TweenSize(size, _, _, _, _, callback)
	self.Size = size
	if type(callback) == "function" then
		task.defer(callback)
	end
	return true
end

function Node:TweenSizeAndPosition(size, position, _, _, _, _, callback)
	self.Size = size
	self.Position = position
	if type(callback) == "function" then
		task.defer(callback)
	end
	return true
end

function NodeMeta.__index(node, key)
	local method = Node[key]
	if method then
		return method
	end
	if EVENT_NAMES[key] then
		return eventSignal(node, key)
	end
	local props = rawget(node, "_props")
	if props[key] ~= nil then
		return props[key]
	end
	for _, child in ipairs(rawget(node, "_children")) do
		if child.Name == key then
			return child
		end
	end
	local real = rawget(node, "_real")
	if real then
		local value = safe(function()
			return real[key]
		end)
		if value ~= nil then
			return value
		end
	end
	return defaultProperty(node, key)
end

function NodeMeta.__newindex(node, key, value)
	if key == "Parent" then
		setParent(node, value)
		return
	end
	local props = rawget(node, "_props")
	props[key] = value
	local real = rawget(node, "_real")
	if real then
		safe(function()
			real[key] = value
		end)
	end
	propertySignal(node, key):Fire()
	eventSignal(node, "Changed"):Fire(key)
end

function NodeMeta.__tostring(node)
	return tostring(node.Name)
end

local function newNode(factory, className)
	return setmetatable({
		__MammozVirtualNode = true,
		_className = className,
		_factory = factory,
		_props = { Name = className },
		_parent = nil,
		_children = {},
		_signals = {},
		_propertySignals = {},
		_attributes = {},
		_real = nil,
		_destroyed = false,
		_focused = false,
	}, NodeMeta)
end

local function virtualTween(target, info, goals)
	local completed = newSignal("Completed", target)
	local tween = { Completed = completed, PlaybackState = Enum.PlaybackState.Begin }
	function tween:Play()
		self.PlaybackState = Enum.PlaybackState.Playing
		for property, value in pairs(goals or {}) do
			target[property] = value
		end
		local duration = tonumber(safe(function() return info.Time end)) or 0
		task.delay(duration, function()
			if self.PlaybackState == Enum.PlaybackState.Playing then
				self.PlaybackState = Enum.PlaybackState.Completed
				completed:Fire(Enum.PlaybackState.Completed)
			end
		end)
	end
	function tween:Cancel()
		self.PlaybackState = Enum.PlaybackState.Cancelled
		completed:Fire(Enum.PlaybackState.Cancelled)
	end
	function tween:Pause()
		self.PlaybackState = Enum.PlaybackState.Paused
	end
	return tween
end

local function tweenService(factory)
	local real = game:GetService("TweenService")
	local service = {}
	function service:Create(target, info, goals)
		if isVirtual(target) then
			return virtualTween(target, info, goals)
		end
		return real:Create(target, info, goals)
	end
	function service:GetValue(alpha, style, direction)
		return real:GetValue(alpha, style, direction)
	end
	service.__MammozFactory = factory
	return service
end

function Proxy.Create(UI, layoutAdapter, config)
	assert(type(UI) == "table", "MammozLegacyProxy.Create expects MammozCompat")
	assert(type(layoutAdapter) == "table", "MammozLegacyProxy.Create expects MammozLegacyLayout")
	config = type(config) == "table" and config or {}

	local factory
	local sessionConfig = table.clone(config)
	sessionConfig.MaterializeAuxiliary = function(screen)
		if factory then
			return factory:Materialize(screen)
		end
		return nil
	end
	sessionConfig.SuppressAuxiliary = function(screen)
		if factory then
			return factory:Suppress(screen)
		end
		return nil
	end
	local session = layoutAdapter.CreateVirtualSession(UI, sessionConfig)
	factory = {
		Real = RealInstance,
		Session = session,
		Config = config,
	}

	function factory.new(first, second, third)
		local className = first == factory and second or first
		local parent = first == factory and third or second
		if not VIRTUAL_CLASSES[className] then
			return RealInstance.new(className, parent)
		end
		local node = newNode(factory, className)
		if className == "ScreenGui" then
			session:Queue(node)
		end
		if parent ~= nil then
			node.Parent = parent
		end
		return node
	end

	function factory:IsVirtual(value)
		return isVirtual(value)
	end

	function factory:Materialize(node)
		if not isVirtual(node) then
			return node
		end
		local parent = rawget(node, "_parent")
		if parent == nil then
			return nil
		end
		return materialize(node, isVirtual(parent) and rawget(parent, "_real") or parent)
	end

	function factory:Suppress(node)
		if isVirtual(node) then
			rawset(node, "_suppressed", true)
		end
		return node
	end

	factory.TweenService = tweenService(factory)
	return factory
end

return Proxy

    end,
    ["MammozCompat.lua"] = function()
-- Mammoz UI compatibility layer for the local scripts.
-- It wraps MammozUI.lib.lua and exposes the older framework APIs:
-- UI.Window -> win:Page -> page:Card -> card:Toggle/Button/Slider/Dropdown/Stepper/Readout.

local function environmentTable()
	return (getgenv and getgenv()) or _G
end

local function rawBaseUrl()
	local env = environmentTable()
	local base = env.__MAMMOZ_RAW_BASE or env.MAMMOZ_RAW_BASE
	if type(base) ~= "string" or base == "" then
		return nil
	end
	base = base:gsub("\\", "/")
	if base:sub(-1) ~= "/" then
		base ..= "/"
	end
	return base
end

local function rawModuleUrl(path)
	local base = rawBaseUrl()
	if not base then
		return nil
	end
	path = tostring(path or ""):gsub("\\", "/"):gsub(" ", "%%20")
	return base .. path
end

local function loadRawModule(path, label)
	local url = rawModuleUrl(path)
	if not url or not (game and loadstring) then
		return nil
	end
	local ok, result = pcall(function()
		return loadstring(game:HttpGet(url, true), label or path)()
	end)
	if ok and type(result) == "table" then
		return result
	end
	return nil
end

-- The standalone distribution registers this loader before it evaluates this
-- module.  Keeping the hook here also means the normal multi-file build and
-- the standalone build expose exactly the same compatibility API.
local function loadBundledModule(path)
	local loader = environmentTable().__MAMMOZ_BUNDLE_LOAD
	if type(loader) ~= "function" then
		return nil
	end
	local ok, result = pcall(loader, path)
	if ok and type(result) == "table" then
		return result
	end
	return nil
end

local function loadMammozBackend()
	local env = environmentTable()
	if type(env.__MAMMOZ_UI_BACKEND) == "table" then
		return env.__MAMMOZ_UI_BACKEND
	end
	local bundledBackend = loadBundledModule("MammozUI.lib.lua")
	if type(bundledBackend) == "table" then
		env.__MAMMOZ_UI_BACKEND = bundledBackend
		return bundledBackend
	end

	local candidates = {
		"Mammoz-Hub-Script/MammozUI.lib.lua",
		"MammozUI.lib.lua",
		"./MammozUI.lib.lua",
	}

	for _, path in ipairs(candidates) do
		if readfile then
			local ok, source = pcall(readfile, path)
			if ok and type(source) == "string" and source ~= "" then
				local loadedOk, result = pcall(function()
					return loadstring(source, "MammozUI")()
				end)
				if loadedOk and type(result) == "table" then
					env.__MAMMOZ_UI_BACKEND = result
					return result
				end
			end
		end

		if loadfile then
			local ok, result = pcall(function()
				return loadfile(path)()
			end)
			if ok and type(result) == "table" then
				env.__MAMMOZ_UI_BACKEND = result
				return result
			end
		end
	end

	local remoteBackend = loadRawModule("MammozUI.lib.lua", "MammozUI")
	if type(remoteBackend) == "table" then
		env.__MAMMOZ_UI_BACKEND = remoteBackend
		return remoteBackend
	end

	error("MammozCompat.lua: MammozUI.lib.lua was not found.", 2)
end

local MammozUI = loadMammozBackend()

local UI = {}

UI.theme = {
	accent = Color3.fromRGB(39, 145, 255),
	band = Color3.fromRGB(83, 193, 255),
	good = Color3.fromRGB(61, 224, 167),
	warn = Color3.fromRGB(247, 191, 72),
	bad = Color3.fromRGB(255, 104, 119),
	text = Color3.fromRGB(235, 247, 255),
	dim = Color3.fromRGB(112, 150, 183),
}

-- All converted scripts share this visual system. A script may opt out only
-- explicitly with AllowCustomTheme, which keeps the default experience aligned
-- with the main Mammoz dashboard instead of each source framework's skin.
UI.LockDashboardTheme = true
UI.DashboardStyle = "main-dashboard"

UI.icon = {
	home = "home",
	bolt = "star",
	pickaxe = "code",
	coin = "star",
	chart = "search",
	list = "code",
	bag = "shield",
	eye = "search",
	target = "search",
	wave = "star",
	grid = "home",
	map = "home",
	sword = "shield",
	flask = "star",
	gear = "gear",
	user = "user",
	shield = "shield",
	star = "star",
}

UI.Options = {}
UI.Toggles = {}
UI.Tabs = {}
UI.TabButtons = {}
UI.Labels = {}
UI.Scheme = {}
UI.Unloaded = false

local environment = environmentTable()
environment.__MAMMOZ_RUNTIME_ERRORS = type(environment.__MAMMOZ_RUNTIME_ERRORS) == "table"
	and environment.__MAMMOZ_RUNTIME_ERRORS or {}
UI.RuntimeErrors = environment.__MAMMOZ_RUNTIME_ERRORS

local function traceback(message)
	return debug and debug.traceback and debug.traceback(tostring(message), 2) or tostring(message)
end

local function callbackContext(callback)
	if debug and type(debug.info) == "function" then
		local ok, source, line, name = pcall(debug.info, callback, "sln")
		if ok then
			local label = tostring(name or "callback")
			if source and source ~= "" then
				label ..= " @ " .. tostring(source)
			end
			if tonumber(line) then
				label ..= ":" .. tostring(line)
			end
			return label
		end
	end
	return "callback"
end

local reportingError = false
local function reportRuntimeError(context, err)
	local entry = {
		Time = os.date and os.date("%H:%M:%S") or tostring(math.floor(os.clock())),
		Context = tostring(context or "Runtime"),
		Error = tostring(err or "Unknown error"),
	}
	UI.RuntimeErrors[#UI.RuntimeErrors + 1] = entry
	while #UI.RuntimeErrors > 40 do
		table.remove(UI.RuntimeErrors, 1)
	end
	if type(warn) == "function" then
		warn(("[Mammoz] %s: %s"):format(entry.Context, entry.Error))
	end
	if not reportingError then
		reportingError = true
		local window = UI.LastWindow
		if window and type(window.ShowRuntimeError) == "function" then
			pcall(window.ShowRuntimeError, window, entry)
		end
		reportingError = false
	end
	return entry
end

function UI:ReportError(context, err)
	return reportRuntimeError(context, err)
end

environment.__MAMMOZ_REPORT_ERROR = function(context, err)
	return reportRuntimeError(context, err)
end

local function placeId()
	local ok, value = pcall(function()
		return game.PlaceId
	end)
	return ok and tostring(value) or "0"
end

local function sanitizePathPart(value)
	local text = tostring(value or "default"):gsub("[^%w%._%-]", "_")
	text = text:gsub("_+", "_")
	return text ~= "" and string.sub(text, 1, 80) or "default"
end

local function configNamespace()
	return sanitizePathPart(UI.ConfigNamespace or "default")
end

local function configStore()
	environment.__MAMMOZ_UI_CONFIG_STORE = type(environment.__MAMMOZ_UI_CONFIG_STORE) == "table"
		and environment.__MAMMOZ_UI_CONFIG_STORE or {}
	local key = placeId() .. "|" .. configNamespace()
	environment.__MAMMOZ_UI_CONFIG_STORE[key] = type(environment.__MAMMOZ_UI_CONFIG_STORE[key]) == "table"
		and environment.__MAMMOZ_UI_CONFIG_STORE[key] or {}
	return environment.__MAMMOZ_UI_CONFIG_STORE[key]
end

local function configDirectory()
	return "Mammoz-Hub-Script/configs/" .. sanitizePathPart(placeId()) .. "/" .. configNamespace()
end

local function configPath(name)
	return configDirectory() .. "/" .. sanitizePathPart(name) .. ".json"
end

local function ensureConfigDirectory()
	if type(makefolder) ~= "function" then
		return false
	end
	for _, path in ipairs({
		"Mammoz-Hub-Script",
		"Mammoz-Hub-Script/configs",
		"Mammoz-Hub-Script/configs/" .. sanitizePathPart(placeId()),
		configDirectory(),
	}) do
		local exists = false
		if type(isfolder) == "function" then
			local ok, result = pcall(isfolder, path)
			exists = ok and result == true
		end
		if not exists then
			pcall(makefolder, path)
		end
	end
	return true
end

local function serializeValue(value, depth)
	depth = depth or 0
	if depth > 8 then
		return nil
	end
	local luaType = type(value)
	if luaType == "nil" or luaType == "string" or luaType == "number" or luaType == "boolean" then
		return value
	end
	local robloxType = typeof(value)
	if robloxType == "Color3" then
		return { __mammozType = "Color3", R = value.R, G = value.G, B = value.B }
	elseif robloxType == "Vector2" or robloxType == "Vector3" then
		return { __mammozType = robloxType, X = value.X, Y = value.Y, Z = value.Z }
	elseif robloxType == "EnumItem" then
		return { __mammozType = "EnumItem", Value = tostring(value) }
	elseif luaType == "table" then
		local result = {}
		for key, child in pairs(value) do
			local encoded = serializeValue(child, depth + 1)
			if encoded ~= nil then
				result[tostring(key)] = encoded
			end
		end
		return result
	end
	return tostring(value)
end

local function deserializeValue(value)
	if type(value) ~= "table" then
		return value
	end
	if value.__mammozType == "Color3" then
		return Color3.new(tonumber(value.R) or 0, tonumber(value.G) or 0, tonumber(value.B) or 0)
	elseif value.__mammozType == "Vector2" then
		return Vector2.new(tonumber(value.X) or 0, tonumber(value.Y) or 0)
	elseif value.__mammozType == "Vector3" then
		return Vector3.new(tonumber(value.X) or 0, tonumber(value.Y) or 0, tonumber(value.Z) or 0)
	elseif value.__mammozType == "EnumItem" then
		local enumType, itemName = tostring(value.Value or ""):match("^Enum%.([^.]+)%.(.+)$")
		local ok, item = pcall(function()
			return enumType and itemName and Enum[enumType][itemName]
		end)
		return ok and item or value.Value
	end
	local result = {}
	for key, child in pairs(value) do
		if key ~= "__mammozType" then
			local numericKey = tonumber(key)
			result[numericKey and math.floor(numericKey) == numericKey and numericKey or key] = deserializeValue(child)
		end
	end
	return result
end

local function httpService()
	local ok, service = pcall(function()
		return game:GetService("HttpService")
	end)
	return ok and service or nil
end

function UI:SaveConfig(name)
	local store = configStore()
	local key = tostring(name or "default")
	local data = {}
	for id, proxy in pairs(UI.Options) do
		local ok, value = pcall(function()
			return type(proxy.Get) == "function" and proxy:Get() or proxy.Value
		end)
		if ok then
			data[id] = value
		end
	end
	store[key] = data
	local service = httpService()
	if service and type(writefile) == "function" then
		local ok, err = pcall(function()
			ensureConfigDirectory()
			writefile(configPath(key), service:JSONEncode({
				Version = 1,
				PlaceId = placeId(),
				Namespace = configNamespace(),
				Values = serializeValue(data),
			}))
		end)
		if not ok then
			reportRuntimeError("SaveConfig " .. key, err)
		end
	end
	return true
end

function UI:LoadConfig(name)
	local key = tostring(name or "default")
	local data = configStore()[key]
	if type(data) ~= "table" and type(readfile) == "function" then
		local service = httpService()
		local path = configPath(key)
		local exists = true
		if type(isfile) == "function" then
			local ok, result = pcall(isfile, path)
			exists = ok and result == true
		end
		if service and exists then
			local ok, decoded = pcall(function()
				local payload = service:JSONDecode(readfile(path))
				return deserializeValue(payload.Values or payload)
			end)
			if ok and type(decoded) == "table" then
				data = decoded
				configStore()[key] = data
			elseif not ok then
				reportRuntimeError("LoadConfig " .. key, decoded)
			end
		end
	end
	if type(data) ~= "table" then
		return false
	end
	for id, value in pairs(data) do
		local proxy = UI.Options[id]
		if proxy then
			pcall(function()
				if type(proxy.Set) == "function" then
					proxy:Set(value)
				elseif type(proxy.SetValue) == "function" then
					proxy:SetValue(value)
				else
					proxy.Value = value
				end
			end)
		end
	end
	return true
end

function UI:SetFlag(id, value)
	local proxy = UI.Options[tostring(id or "")]
	if not proxy then
		return false
	end
	pcall(function()
		if type(proxy.Set) == "function" then
			proxy:Set(value)
		elseif type(proxy.SetValue) == "function" then
			proxy:SetValue(value)
		else
			proxy.Value = value
		end
	end)
	return true
end

function UI:ListConfigs()
	local list, seen = {}, {}
	for name in pairs(configStore()) do
		seen[name] = true
		list[#list + 1] = name
	end
	if type(listfiles) == "function" then
		local ok, files = pcall(listfiles, configDirectory())
		if ok and type(files) == "table" then
			for _, path in ipairs(files) do
				local name = tostring(path):match("([^/\\]+)%.json$")
				if name and not seen[name] then
					seen[name] = true
					list[#list + 1] = name
				end
			end
		end
	end
	table.sort(list)
	return list
end

function UI.t(text)
	return tostring(text or "")
end

local Window = {}
Window.__index = Window

local Page = {}
Page.__index = Page

local Card = {}
Card.__index = Card

local function normalizeIcon(icon)
	if type(icon) == "string" and icon ~= "" then
		local lowered = string.lower(icon)
		if UI.icon[lowered] then
			return UI.icon[lowered]
		end
		for pattern, mapped in pairs({
			["home"] = "home",
			["farm"] = "home",
			["player"] = "user",
			["user"] = "user",
			["setting"] = "gear",
			["gear"] = "gear",
			["wrench"] = "gear",
			["combat"] = "shield",
			["sword"] = "shield",
			["shield"] = "shield",
			["esp"] = "search",
			["eye"] = "search",
			["target"] = "search",
			["search"] = "search",
			["gift"] = "star",
			["reward"] = "star",
			["star"] = "star",
		}) do
			if string.find(lowered, pattern, 1, true) then
				return mapped
			end
		end
		return "code"
	end
	return "code"
end

local function call(callback, ...)
	if type(callback) == "function" then
		local args = table.pack(...)
		local context = callbackContext(callback)
		task.spawn(function()
			local ok, err = xpcall(function()
				callback(table.unpack(args, 1, args.n))
			end, traceback)
			if not ok then
				reportRuntimeError(context, err)
			end
		end)
	end
end

local function mirrorButtonText(button, label)
	if not (button and label) then
		return
	end
	button.TextTransparency = 1
	button:GetPropertyChangedSignal("Text"):Connect(function()
		label.Text = button.Text
	end)
end

local function textOf(value)
	local ok, result = pcall(value)
	if ok then
		return tostring(result)
	end
	return "-"
end

function UI.Window(first, second)
	local config = first == UI and (second or {}) or (first or {})
	config = config or {}
	UI.Unloaded = false
	local useCustomTheme = UI.LockDashboardTheme == false or config.AllowCustomTheme == true
	if not useCustomTheme then
		UI.theme.accent = Color3.fromRGB(39, 145, 255)
		UI.theme.band = Color3.fromRGB(83, 193, 255)
		UI.theme.good = Color3.fromRGB(61, 224, 167)
		UI.theme.warn = Color3.fromRGB(247, 191, 72)
		UI.theme.bad = Color3.fromRGB(255, 104, 119)
		UI.theme.text = Color3.fromRGB(235, 247, 255)
		UI.theme.dim = Color3.fromRGB(112, 150, 183)
	end
	local title = config.Title or config.title or config.Name or config.name or "Mammoz"
	local accentTitle = config.AccentTitle or config.accentTitle
	if accentTitle and accentTitle ~= "" then
		title = tostring(title) .. " " .. tostring(accentTitle)
	end

	local requestedSize = config.Size
	if typeof(requestedSize) == "UDim2" and requestedSize.X.Scale == 0 and requestedSize.Y.Scale == 0 then
		requestedSize = UDim2.fromOffset(math.max(900, requestedSize.X.Offset), math.max(600, requestedSize.Y.Offset))
	elseif typeof(requestedSize) ~= "UDim2" then
		local width = math.max(900, tonumber(config.width or config.Width) or 1120)
		local height = math.max(600, tonumber(config.height or config.Height) or 700)
		requestedSize = UDim2.fromOffset(width, height)
	end
	local raw = MammozUI:CreateWindow({
		Title = title,
		Name = config.Name or config.name or "MammozHubUI",
		BadgeText = config.badge or config.BadgeText or config.Subtitle or config.subtitle or config.Author or title,
		Accent = useCustomTheme and (config.Accent or UI.theme.accent) or UI.theme.accent,
		Theme = useCustomTheme and type(config.MammozTheme) == "table" and config.MammozTheme or nil,
		Size = requestedSize,
		OnClose = config.OnClose or config.Destroying or config.destroying,
	})

	local self = setmetatable({
		raw = raw,
		gui = raw.screen,
		Gui = raw.screen,
		Container = raw.screen,
		status = "",
		stats = {},
		masterValue = false,
		masterLabel = "Master",
		masterCallback = nil,
		homePage = nil,
		homeStatus = nil,
		homeStats = {},
		homeMasterRefresh = nil,
		pages = {},
	}, Window)
	UI.ScreenGui = raw.screen
	UI.LastWindow = self
	if UI.NotifySide and type(raw.setNotifySide) == "function" then
		raw:setNotifySide(UI.NotifySide)
	end
	if UI.DPIScale and type(raw.setDPIScale) == "function" then
		raw:setDPIScale(UI.DPIScale)
	end
	if UI.Font and type(raw.setFont) == "function" then
		raw:setFont(UI.Font)
	end
	if config.ToggleKey or config.ToggleKeybind then
		self:SetToggleKey(config.ToggleKey or config.ToggleKeybind)
	end
	self.ConfigManager = {
		CreateConfig = function()
			return true
		end,
		LoadConfig = function()
			return true
		end,
		SaveConfig = function()
			return true
		end,
	}

	return self
end

function Window:Destroy()
	local result = self.raw:Destroy()
	if UI.LastWindow == self then
		UI.LastWindow = nil
		UI.ScreenGui = nil
	end
	return result
end

function Window:SetStatus(text)
	self.status = tostring(text or "")
	if self.raw and type(self.raw.setHeaderStatus) == "function" then
		local statusKind = string.find(string.lower(self.status), "error", 1, true) and "error"
			or string.find(string.lower(self.status), "warn", 1, true) and "warn"
			or nil
		self.raw:setHeaderStatus(self.status ~= "" and self.status or "SYSTEM ONLINE", statusKind)
	end
	if self.homeStatus then
		self.homeStatus.Text = self.status
	end

	local badge = self.raw.supportBadge
	if badge then
		local label = badge:FindFirstChildWhichIsA("TextLabel")
		if label then
			label.Text = self.status ~= "" and string.sub(self.status, 1, 34) or "UI Library"
		end
	end
end

function Window:SetStat(index, value, label)
	index = tonumber(index) or 1
	self.stats[index] = {
		value = tostring(value or ""),
		label = tostring(label or ""),
	}

	local statLabel = self.homeStats[index]
	if statLabel then
		local item = self.stats[index]
		statLabel.Text = item.label ~= "" and (item.value .. "  " .. item.label) or item.value
	end
end

function Window:SetMaster(value, label)
	self.masterValue = value and true or false
	if label then
		self.masterLabel = tostring(label)
	end
	if self.homeMasterRefresh then
		self.homeMasterRefresh()
	end
end

function Window:OnMaster(callback)
	self.masterCallback = callback
end

function Window:Refresh()
	if self.homeStatus then
		self.homeStatus.Text = self.status or ""
	end
	for index, item in pairs(self.stats) do
		self:SetStat(index, item.value, item.label)
	end
end

function Window:Home()
	if self.homePage then
		self.raw:SelectPage(self.homePage.raw)
		return self.homePage
	end

	local page = self:Page("HOME", "home")
	local card = page:Card("STATUS", 0)
	self.homeStatus = card.raw:AddLabel(self.status ~= "" and self.status or "Ready", true)

	for i = 1, 3 do
		local item = self.stats[i] or { value = "-", label = "" }
		self.homeStats[i] = card.raw:AddLabel(item.label ~= "" and (item.value .. "  " .. item.label) or item.value, true)
	end

	local refreshMaster
	card:Toggle(self.masterLabel, self.masterValue, function(on)
		self.masterValue = on
		call(self.masterCallback, on)
	end)
	refreshMaster = function() end
	self.homeMasterRefresh = refreshMaster

	self.homePage = page
	self.raw:SelectPage(page.raw)
	return page
end

function Window:Page(name, icon)
	local rawPage = self.raw:CreatePage(tostring(name or "Page"), normalizeIcon(icon))
	local page = setmetatable({
		raw = rawPage,
		window = self,
	}, Page)
	self.pages[#self.pages + 1] = page
	return page
end

function Page:Card(title, order)
	local rawCard = self.raw:CreateCard(tostring(title or "Card"), order)
	return setmetatable({
		raw = rawCard,
		page = self,
		window = self.window,
	}, Card)
end

function Card:Accent()
	return self
end

function Card:Label(text, note)
	return self.raw:AddLabel(tostring(text or ""), note ~= false)
end

function Card:Button(text, callback, tone)
	local button, label
	button, label = self.raw:AddButton(tostring(text or "Button"), function()
		call(callback, button, label)
	end)
	button.Text = tostring(text or "Button")
	mirrorButtonText(button, label)
	return button
end

function Card:Toggle(text, default, callback, hint, tone)
	local row = self.raw:AddToggle(tostring(text or "Toggle"), default and true or false, function(value)
		call(callback, value)
	end)
	if hint and hint ~= "" then
		self.raw:AddLabel(tostring(hint), true)
	end
	return row
end

function Card:Slider(text, min, max, default, callback, suffix)
	return self.raw:AddSlider(tostring(text or "Slider"), min or 0, max or 100, default or min or 0, function(value)
		if math.abs(value - math.floor(value + 0.5)) < 0.001 then
			value = math.floor(value + 0.5)
		end
		call(callback, value)
	end)
end

function Card:Dropdown(text, options, default, callback)
	options = type(options) == "table" and options or {}
	return self.raw:AddDropdown(tostring(text or "Dropdown"), options, default or options[1], function(value)
		call(callback, value)
	end)
end

function Card:Stepper(text, getter, callback, hint, tone)
	local labelText = tostring(text or "Value")
	local valueLabel = self.raw:AddLabel(labelText .. ": " .. textOf(getter), false)

	local function refresh()
		valueLabel.Text = labelText .. ": " .. textOf(getter)
	end

	local minus = self:Button("- " .. labelText, function()
		if type(callback) == "function" then
			callback(-1)
		end
		refresh()
	end)
	local plus = self:Button("+ " .. labelText, function()
		if type(callback) == "function" then
			callback(1)
		end
		refresh()
	end)

	if hint and hint ~= "" then
		self.raw:AddLabel(tostring(hint), true)
	end

	refresh()
	return refresh, minus, plus
end

function Card:Readout(count, colorFn)
	count = tonumber(count) or 8
	local labels = {}
	for i = 1, count do
		labels[i] = self.raw:AddLabel("", true)
		labels[i].Font = Enum.Font.Code
		labels[i].TextSize = 10
		labels[i].TextXAlignment = Enum.TextXAlignment.Left
	end

	local readout = {}

	function readout:set(lines)
		lines = type(lines) == "table" and lines or {}
		for i = 1, count do
			local text = tostring(lines[i] or "")
			labels[i].Text = text
			if type(colorFn) == "function" then
				local ok, color = pcall(colorFn, text, i)
				if ok and typeof(color) == "Color3" then
					labels[i].TextColor3 = color
				end
			end
		end
	end

	function readout:Set(lines)
		return self:set(lines)
	end

	return readout
end

local function valueFrom(config, ...)
	if type(config) ~= "table" then
		return nil
	end
	for _, key in ipairs({ ... }) do
		if config[key] ~= nil then
			return config[key]
		end
	end
	return nil
end

local function makeControlProxy(refresh)
	local proxy = {}
	local callbacks = {}
	function proxy:SetValue(value)
		self.Value = value
		if refresh then
			refresh(value)
		end
		for _, callback in ipairs(callbacks) do
			call(callback, value)
		end
	end
	function proxy:Set(value)
		return self:SetValue(value)
	end
	function proxy:SetValues(value)
		return self:SetValue(value)
	end
	-- Sampluy controls expose Replace(value) to set the displayed state
	-- without re-running the script callback (used to un-check a toggle from
	-- inside its own callback without recursion).
	function proxy:Replace(value)
		local callbacksToRestore = callbacks
		callbacks = {}
		self:SetValue(value)
		callbacks = callbacksToRestore
		return self
	end
	function proxy:Get()
		return self.Value
	end
	function proxy:SetOptions()
		return self
	end
	function proxy:Refresh()
		return self
	end
	function proxy:Update()
		return self
	end
	function proxy:SetDesc()
		return self
	end
	function proxy:SetText(value)
		return self:SetValue(value)
	end
	function proxy:SetValueRGB(value)
		return self:SetValue(value)
	end
	function proxy:OnChanged(callback)
		if type(callback) == "function" then
			callbacks[#callbacks + 1] = callback
		end
		return self
	end
	return proxy
end

function Window:Notify(config, body, kind)
	if type(config) == "table" then
		return self.raw:Notify(config.Title or config.title or "Notice", config.Content or config.content or config.Body or config.body or "", kind or config.Type or config.type or config.Kind or config.kind)
	end
	return self.raw:Notify(tostring(config or "Notice"), tostring(body or ""), kind)
end

function Window:Toast(config, body, kind)
	if type(config) == "table" then
		return self:Notify({
			Title = config.Title or config.title or config.Name or config.name or "Notice",
			Content = config.Content or config.content or config.Subtitle or config.subtitle
				or config.Description or config.description or config.Body or config.body or "",
			Type = config.Type or config.type or kind,
		})
	end
	return self:Notify(config, body, kind)
end

