local __mammozCache = {}
local function __mammozLoad(name)
    if __mammozCache[name] ~= nil then
        return __mammozCache[name]
    end
    local factory = __mammozFactories[name]
    if type(factory) ~= "function" then
        error("Mammoz standalone module was not found: " .. tostring(name), 2)
    end
    local result = factory()
    __mammozCache[name] = result
    return result
end

__mammozEnvironment.__MAMMOZ_BUNDLE_LOAD = __mammozLoad
local __mammozUI = __mammozLoad("MammozCompat.lua")
__mammozEnvironment.__MAMMOZ_SHARED_UI = __mammozUI
__mammozEnvironment.__MAMMOZ_UI_REVISION = __mammozApiRevision
return __mammozUI
